// 64 nguyên tắc hành xử rút từ Đại tượng truyện (大象傳) — mỗi quẻ một câu "quân tử dĩ…" (君子以…; vài quẻ là 先王以, 后以, 大人以, 上以).
// zh: nguyên văn câu Đại tượng, chép đúng data/nguyen-van.js (nguồn Wikisource 周易, phạm vi công cộng); tool tools/kiem-tra-nguyen-tac.mjs dò lại trong nguon/zh/NN.txt.
// hv: âm Hán Việt, một âm tiết một chữ Hán. dich: dịch nghĩa của kho.
// nguyenTac, giaiThich, tinhHuong, viecHomNay, nhom: BẢN BIÊN SOẠN CỦA KHO (24/10/2026) theo định hướng Kinh Dịch là cẩm nang sống,
// KHÔNG phải lời người xưa; tình huống là chuyện đời nay dựng lên để soi nguyên tắc, tên người và địa danh chỉ để câu chuyện thật, không chỉ ai cụ thể.
// nhom: Tu thân | Làm việc | Ứng xử | Gia đình | Lãnh đạo | Tiền của | Thời thế.
window.KD_NGUYEN_TAC = [
{n: 1, zh: "天行健，君子以自強不息。",
 hv: "Thiên hành kiện, quân tử dĩ tự cường bất tức.",
 dich: "Trời vận hành mạnh mẽ không ngừng; người quân tử noi theo mà tự mình gắng sức, không nghỉ.",
 nguyenTac: "Tự cường không nghỉ.",
 giaiThich: "Càn chồng Càn: trời trên trời dưới, toàn hào dương. Trời không có ngày nghỉ, mặt trời không bỏ buổi nào; sức mạnh ở đây không phải cơn bùng nổ mà là sự đều đặn. Người theo tượng ấy thì lấy cái đều làm sức, mỗi ngày tiến một chút, không đợi hứng.",
 tinhHuong: "Anh Hưng, 38 tuổi, kỹ sư cơ điện ở Biên Hòa, muốn đọc được tài liệu máy của hãng Đức nhưng tiếng Anh mất gốc. Anh không đăng ký khóa cấp tốc mà đặt lịch 25 phút mỗi sáng trước giờ đi làm, nghỉ lễ cũng không bỏ. Sau hai năm anh đọc được catalogue và trả lời email kỹ thuật, được giao phụ trách dự án có chuyên gia nước ngoài. Thứ giúp anh không phải một quyết tâm lớn mà là 25 phút không gián đoạn.",
 viecHomNay: "Chọn một việc mình đang bỏ dở và làm nó 20 phút, không cần xong.",
 nhom: "Tu thân"},
{n: 2, zh: "地勢坤，君子以厚德載物。",
 hv: "Địa thế khôn, quân tử dĩ hậu đức tải vật.",
 dich: "Thế đất thuận và dày; người quân tử noi theo mà lấy đức dày chở lấy muôn vật.",
 nguyenTac: "Lòng dày thì gánh được người.",
 giaiThich: "Khôn chồng Khôn: đất trên đất dưới, toàn hào âm. Đất không chọn vật để chở, sạch bẩn gì cũng đặt lên được, vì nó dày. Người theo tượng ấy thì rèn cho mình đủ sức chịu để nhận lấy cả lỗi của người khác mà không oằn.",
 tinhHuong: "Chị Thu quản lý xưởng in 40 người ở Tân Phú. Một nhân viên mới nhập sai màu cho lô bao bì của khách lâu năm, thiệt 60 triệu. Chị gọi khách xin lỗi và nhận trách nhiệm về xưởng, không nêu tên người làm sai, rồi về ngồi với cậu nhân viên dò lại từng bước để cậu tự thấy chỗ hỏng. Khách giữ hợp đồng, cậu nhân viên ở lại và sau này là người kiểm màu kỹ nhất xưởng.",
 viecHomNay: "Khi có người làm hỏng việc, hỏi “sửa thế nào” trước khi hỏi “tại sao”.",
 nhom: "Ứng xử"},
{n: 3, zh: "雲雷，屯；君子以經綸。",
 hv: "Vân lôi, Truân; quân tử dĩ kinh luân.",
 dich: "Mây và sấm là quẻ Truân; người quân tử noi theo mà sắp xếp, gây dựng như gỡ tơ dệt sợi.",
 nguyenTac: "Lúc rối, bắt đầu từ sắp xếp.",
 giaiThich: "Khảm (mây, nước) trên, Chấn (sấm) dưới: sấm đã động mà mưa chưa rơi, mọi thứ ứ đầy và lộn xộn như lúc vạn vật mới sinh. Kinh luân là gỡ tơ và chải sợi: việc đầu tiên không phải dệt, mà là gỡ cho ra đầu mối. Người theo tượng ấy thì gặp rối không lao vào làm, mà kê lại từng việc cho có thứ tự.",
 tinhHuong: "Ba người bạn góp vốn mở quán cà phê ở Thủ Đức. Tháng đầu ai cũng làm mọi việc: cùng pha, cùng mua, cùng trả lời khách, cuối tháng không biết lỗ ở đâu. Họ đóng quán một buổi chiều, kẻ một bảng ba cột: Nhi lo nguyên liệu và sổ tiền, Khải lo quầy và nhân viên, Tâm lo mạng xã hội và khách đoàn; tiền vào ra ghi mỗi tối trước khi đóng cửa. Tháng sau quán vẫn vắng, nhưng lần đầu họ biết chính xác vắng vì đâu.",
 viecHomNay: "Viết ra giấy mọi việc đang dang dở, rồi đánh số 1, 2, 3 theo thứ tự làm.",
 nhom: "Làm việc"},
{n: 4, zh: "山下出泉，蒙；君子以果行育德。",
 hv: "Sơn hạ xuất tuyền, Mông; quân tử dĩ quả hạnh dục đức.",
 dich: "Dưới núi có suối chảy ra là quẻ Mông; người quân tử noi theo mà hành động dứt khoát, nuôi đức từ từ.",
 nguyenTac: "Làm thì dứt khoát, nuôi thì từ từ.",
 giaiThich: "Cấn (núi) trên, Khảm (suối) dưới: mạch nước dưới chân núi còn nhỏ nhưng đã biết chảy; nó không hỏi đường, cứ chảy rồi thành suối. Mông là trẻ nhỏ, là người mới học. Học thì phải làm ngay một việc nhỏ cho dứt điểm, còn cái đức, cái nền thì để thời gian bồi dần như nước ngấm.",
 tinhHuong: "Bé Bảo lớp 6 ở Đà Nẵng sợ nước, đi học bơi ba buổi chỉ đứng ôm thành bể. Bố không giảng về lợi ích của bơi nữa mà giao mỗi buổi một việc duy nhất: hôm nay úp mặt xuống nước đếm đến năm, hôm sau thả nổi mười giây, hôm sau nữa đạp chân bám ván một chiều bể. Hai tuần sau Bảo bơi được mười mét; cái tự tin đến sau cái làm được, không đến trước.",
 viecHomNay: "Việc đang học dở, làm trọn một bài tập nhỏ nhất ngay hôm nay thay vì xem thêm.",
 nhom: "Tu thân"},
{n: 5, zh: "雲上於天，需；君子以飲食宴樂。",
 hv: "Vân thượng ư thiên, Nhu; quân tử dĩ ẩm thực yến lạc.",
 dich: "Mây đã lên trời mà chưa mưa là quẻ Nhu; người quân tử noi theo mà ăn uống, nghỉ ngơi, vui vẻ chờ thời.",
 nguyenTac: "Chờ thì nuôi sức, đừng sốt ruột.",
 giaiThich: "Khảm (mây) trên Càn (trời): mây đã tụ, mưa chắc chắn sẽ xuống, nhưng không ai giục được. Chờ mà nóng ruột là hao sức vô ích. Người theo tượng ấy thì dùng thời gian chờ để ăn ngủ cho đủ, giữ tinh thần, để khi việc đến còn sức mà làm.",
 tinhHuong: "Anh Toàn nộp hồ sơ vào một công ty Nhật ở khu công nghiệp Thăng Long, được báo kết quả sau sáu tuần. Tuần đầu anh gửi email hỏi hai lần, mất ngủ, cáu với vợ. Sau anh tự đặt luật: không hỏi nữa, mỗi ngày đi bộ buổi tối, học thêm một bài tiếng Nhật, nhận một việc thời vụ ngắn. Khi được gọi phỏng vấn vòng hai, anh là người tỉnh táo nhất phòng.",
 viecHomNay: "Việc đang chờ kết quả, tắt thông báo và đi ngủ đúng giờ tối nay.",
 nhom: "Thời thế"},
{n: 6, zh: "天與水違行，訟；君子以作事謀始。",
 hv: "Thiên dữ thủy vi hành, Tụng; quân tử dĩ tác sự mưu thủy.",
 dich: "Trời và nước đi ngược chiều nhau là quẻ Tụng; người quân tử noi theo mà làm việc gì cũng tính kỹ từ lúc bắt đầu.",
 nguyenTac: "Thỏa thuận rõ từ đầu để khỏi cãi về sau.",
 giaiThich: "Càn (trời) đi lên, Khảm (nước) chảy xuống: hai bên càng đi càng xa, đó là mầm của tranh chấp. Kiện tụng không bắt đầu ở tòa mà ở chỗ lúc đầu không nói rõ. Người theo tượng ấy thì dồn công sức vào khâu đầu: ai góp gì, được gì, lúc tách ra thì sao, viết xuống khi còn vui vẻ.",
 tinhHuong: "Hai anh em Dũng và Đạt chung tiền mua một miếng đất ở Đức Hòa, Long An, Dũng góp bảy phần, Đạt góp ba, sổ đứng tên Đạt vì anh ở gần. Không ai viết giấy vì “anh em ruột”. Ba năm sau đất lên giá gấp đôi, vợ Đạt bảo công giữ đất phải tính thêm, hai nhà không nói chuyện cả Tết. Một tờ giấy tay có chữ ký hai vợ chồng mỗi bên, ghi tỷ lệ và cách chia, mất mười phút lúc mua, sẽ không mất một gia đình.",
 viecHomNay: "Việc đang bàn chung tiền hay chung sức với ai, viết thành ba dòng rồi gửi cho người đó xác nhận.",
 nhom: "Tiền của"},
{n: 7, zh: "地中有水，師；君子以容民畜衆。",
 hv: "Địa trung hữu thủy, Sư; quân tử dĩ dung dân súc chúng.",
 dich: "Trong lòng đất có nước là quẻ Sư; người quân tử noi theo mà bao dung dân, nuôi chứa đám đông.",
 nguyenTac: "Nuôi người lúc nhàn để có người lúc cần.",
 giaiThich: "Khôn (đất) trên Khảm (nước) dưới: nước ngầm ẩn trong đất, không thấy nhưng đào là có. Quân đội thời xưa nằm trong dân, lúc bình thường là nông dân, khi cần mới thành lính. Người theo tượng ấy thì nuôi dưỡng người của mình ngay khi chưa cần đến, vì đến lúc cần mới đi tìm thì không kịp.",
 tinhHuong: "Anh Phúc chủ xưởng gỗ 25 thợ ở Thuận An, Bình Dương. Năm đơn hàng xuất khẩu sụt, nhiều xưởng quanh đó cho nghỉ việc; anh giữ đủ người, giảm giờ làm nhưng giữ lương cứng, dùng thời gian rảnh cho thợ trẻ học vẽ CAD và thợ già dạy ghép mộng. Khi đơn hàng quay lại, xưởng anh là nơi duy nhất trong khu nhận được đơn gấp vì còn nguyên đội thợ.",
 viecHomNay: "Hỏi một người trong đội mình đang muốn học thêm điều gì và ghi lại.",
 nhom: "Lãnh đạo"},
{n: 8, zh: "地上有水，比；先王以建萬國，親諸侯。",
 hv: "Địa thượng hữu thủy, Tỷ; tiên vương dĩ kiến vạn quốc, thân chư hầu.",
 dich: "Trên mặt đất có nước là quẻ Tỷ; các vua đời trước noi theo mà dựng nên muôn nước, thân thiết với chư hầu.",
 nguyenTac: "Chủ động gần người quanh mình.",
 giaiThich: "Khảm (nước) trên Khôn (đất): nước lan trên mặt đất, chỗ nào cũng thấm vào, đất với nước không có kẽ hở. Tỷ là gần gũi, nương tựa nhau. Vua xưa chia đất lập nước rồi thân với từng chư hầu; người nay thì dựng lấy mạng lưới quanh mình bằng cách đến trước, chào trước.",
 tinhHuong: "Chị Hạnh mới chuyển về một chung cư ở Hà Đông, không quen ai. Tuần đầu chị gõ cửa hai nhà sát vách biếu ít bánh quê, vào nhóm cư dân, nhận việc giữ chìa khóa phòng sinh hoạt chung. Ba tháng sau con chị sốt cao lúc hai giờ sáng, chồng đi công tác, chị nhắn vào nhóm là có anh hàng xóm tầng trên xuống chở hai mẹ con đi viện. Mạng lưới đó không tự có; chị đã dựng nó lúc chưa cần.",
 viecHomNay: "Nhắn tin hỏi thăm một người quen mà mình đã lâu không liên lạc, không nhờ vả gì.",
 nhom: "Ứng xử"},
{n: 9, zh: "風行天上，小畜，君子以懿文德。",
 hv: "Phong hành thiên thượng, Tiểu Súc; quân tử dĩ ý văn đức.",
 dich: "Gió thổi trên trời là quẻ Tiểu Súc; người quân tử noi theo mà trau chuốt văn vẻ và đức hạnh.",
 nguyenTac: "Chưa làm được việc lớn thì trau cái nhỏ.",
 giaiThich: "Tốn (gió) trên Càn (trời): gió có thể dồn mây nhưng chưa làm được mưa, sức còn nhỏ, chỉ chứa được ít. Lúc chưa đủ lực làm việc lớn thì làm cho mình đẹp hơn ở những chỗ nhỏ: lời nói, chữ viết, cách cư xử. Đó là vốn tích dần cho ngày đủ sức.",
 tinhHuong: "Anh Khoa 29 tuổi muốn mở công ty thiết kế nội thất nhưng vốn chưa đủ, khách chưa có. Thay vì vay nóng để mở cho bằng được, anh dùng hai năm đi làm thuê để học đọc báo cáo tài chính, viết mỗi tuần một bài về vật liệu trên trang cá nhân, tập trình bày trước khách thay cho sếp. Đến khi mở, anh đã có 2.000 người theo dõi và ba khách đầu tiên đến từ những bài viết đó.",
 viecHomNay: "Sửa lại cho gọn một email hay một tin nhắn công việc trước khi gửi.",
 nhom: "Tu thân"},
{n: 10, zh: "上天下澤，履；君子以辨上下，定民志。",
 hv: "Thượng thiên hạ trạch, Lý; quân tử dĩ biện thượng hạ, định dân chí.",
 dich: "Trên là trời, dưới là đầm, là quẻ Lý; người quân tử noi theo mà phân rõ trên dưới, làm yên lòng người.",
 nguyenTac: "Vai nào ra vai nấy, ai cũng yên.",
 giaiThich: "Càn (trời) trên Đoài (đầm) dưới: trời ở trên, đầm ở dưới, đúng chỗ của mỗi thứ, không tranh nhau. Lý là giày, là bước đi, là lễ: biết mình đứng ở đâu thì bước không giẫm lên người khác. Khi vai trò rõ, người ta không phải phấp phỏng dò ý nhau nữa.",
 tinhHuong: "Linh 26 tuổi được cất lên làm trưởng nhóm marketing, trong nhóm có Phương là bạn cùng phòng ký túc xá ngày xưa. Tháng đầu Linh ngại giao việc cho bạn, Phương cũng lờ lịch họp vì “bạn mình thôi mà”, cả nhóm nhìn vào và rối. Linh hẹn Phương đi ăn tối, nói thẳng: trong giờ làm, Linh là trưởng nhóm và sẽ giao việc, nhận xét như với mọi người; ngoài giờ vẫn là bạn. Phương thở phào vì chính cô cũng không biết phải cư xử thế nào.",
 viecHomNay: "Trong một việc đang rối, nói rõ với người liên quan ai quyết phần nào.",
 nhom: "Ứng xử"},
{n: 11, zh: "天地交，泰；后以財成天地之道，輔相天地之宜，以左右民。",
 hv: "Thiên địa giao, Thái; hậu dĩ tài thành thiên địa chi đạo, phụ tướng thiên địa chi nghi, dĩ tả hữu dân.",
 dich: "Trời đất giao hòa là quẻ Thái; bậc vua noi theo mà cắt xén cho thành đạo trời đất, bồi giúp cho hợp lẽ trời đất, để nâng đỡ dân.",
 nguyenTac: "Lúc thuận, san cho đều và nâng người lên.",
 giaiThich: "Khôn (đất) trên, Càn (trời) dưới: khí trời đi lên, khí đất đi xuống, hai bên gặp nhau, muôn vật thông suốt. Thời tốt là của trời đất cho; việc của người là cắt chỗ thừa, bù chỗ thiếu, để cái tốt ấy đến được từng người. Thuận mà không san sẻ thì cái thuận không bền.",
 tinhHuong: "Công ty vật tư điện của anh Long ở Hải Phòng năm nay lãi gấp đôi nhờ mấy dự án khu công nghiệp. Hội đồng đề xuất thưởng lớn cho ba người ban giám đốc. Anh Long đổi lại: thưởng theo số tháng làm việc cho tất cả 70 người kể cả bảo vệ và tạp vụ, trích một phần lập quỹ cho công nhân học nâng bậc, sửa lại nhà ăn đã dột hai năm. Năm sau thị trường chững, không ai trong công ty xin nghỉ.",
 viecHomNay: "Đang có việc gì thuận lợi, chia bớt một phần lợi ấy cho người đã góp sức, ngay hôm nay.",
 nhom: "Lãnh đạo"},
{n: 12, zh: "天地不交，否；君子以儉德辟難，不可榮以祿。",
 hv: "Thiên địa bất giao, Bĩ; quân tử dĩ kiệm đức tị nạn, bất khả vinh dĩ lộc.",
 dich: "Trời đất không giao nhau là quẻ Bĩ; người quân tử noi theo mà thu mình giữ đức để tránh nạn, không lấy bổng lộc làm vinh.",
 nguyenTac: "Thời xấu, thu mình, không ham lộc.",
 giaiThich: "Càn (trời) trên, Khôn (đất) dưới: trời cứ lên, đất cứ xuống, không gặp nhau, mọi thứ tắc. Thời bế tắc, kẻ xấu lên, người ngay bị ép; lúc ấy lộc đưa đến thường có điều kiện. Người theo tượng ấy thì sống gọn lại, bớt chi tiêu, bớt xuất hiện, và nhất định không đổi sự ngay thẳng lấy bổng lộc.",
 tinhHuong: "Chị Ngọc kế toán trưởng một công ty xây lắp ở Vinh. Giám đốc mới gợi ý chị làm hai bộ hồ sơ khối lượng để thanh toán vượt, bù lại tăng lương và cho cổ phần. Chị từ chối, xin chuyển sang bộ phận thống kê lương thấp hơn, cắt bớt chi tiêu gia đình, âm thầm tìm việc khác. Mười tháng sau công ty bị thanh tra, người thay chị ký hồ sơ bị khởi tố.",
 viecHomNay: "Nếu đang có một khoản lợi đi kèm điều kiện mình không nói được với người nhà, từ chối nó.",
 nhom: "Thời thế"},
{n: 13, zh: "天與火，同人；君子以類族辨物。",
 hv: "Thiên dữ hỏa, Đồng Nhân; quân tử dĩ loại tộc biện vật.",
 dich: "Trời cùng với lửa là quẻ Đồng Nhân; người quân tử noi theo mà xếp theo loại, phân rõ từng việc.",
 nguyenTac: "Hợp sức thì phải biết ai làm gì.",
 giaiThich: "Càn (trời) trên, Ly (lửa) dưới: lửa bốc lên cùng hướng với trời, cùng đi một đường nên gọi là đồng nhân. Nhưng hòa đồng không phải trộn lẫn; muốn nhiều người làm chung thì phải biết ai thuộc loại nào, việc gì thuộc nhóm nào. Phân rõ không phải để chia rẽ mà để hợp mà không rối.",
 tinhHuong: "Anh Việt điều phối dự án phần mềm quản lý bệnh viện với 12 người đến từ ba công ty khác nhau. Hai tuần đầu họp nào cũng đông, ai cũng góp ý mọi phần, không phần nào xong. Anh lập một bảng: cột tên, cột thế mạnh thật, cột phần chịu trách nhiệm, cột người cần hỏi khi vướng; dán ở kênh chung, họp chỉ gọi đúng người của phần đó. Dự án vẫn ba công ty, nhưng từ đó là một đội.",
 viecHomNay: "Trong một nhóm mình đang làm chung, viết ra ai chịu trách nhiệm chính cho từng phần.",
 nhom: "Làm việc"},
{n: 14, zh: "火在天上，大有；君子以遏惡揚善，順天休命。",
 hv: "Hỏa tại thiên thượng, Đại Hữu; quân tử dĩ át ác dương thiện, thuận thiên hưu mệnh.",
 dich: "Lửa ở trên trời là quẻ Đại Hữu; người quân tử noi theo mà chặn điều ác, nêu điều thiện, thuận theo mệnh tốt của trời.",
 nguyenTac: "Có nhiều rồi thì chặn xấu, nêu tốt.",
 giaiThich: "Ly (lửa, mặt trời) trên Càn (trời): mặt trời giữa trời cao, soi khắp, không gì giấu được. Đại Hữu là có lớn: có nhiều người, nhiều của, nhiều việc. Lúc ấy cái xấu nhỏ lẫn vào rất dễ, nên người đứng đầu phải sáng như mặt trời: thấy xấu thì chặn ngay, thấy tốt thì nêu lên cho mọi người cùng thấy.",
 tinhHuong: "Bà Lan có năm nhà thuốc ở Cần Thơ. Một quản lý phát hiện nhân viên nhà thuốc số 3 bán thuốc đã bóc tem hạn dùng cho khách quen. Bà cho nghỉ việc người bán, công bố trong cả hệ thống, đồng thời thưởng và nêu tên người quản lý đã báo, dù việc ấy làm doanh số nhà thuốc đó giảm một tháng. Nhân viên các nhà thuốc còn lại hiểu rõ: ở đây báo cái sai được khen chứ không bị ghét.",
 viecHomNay: "Khen đích danh một việc tốt mà người khác vừa làm, trước mặt người thứ ba.",
 nhom: "Lãnh đạo"},
{n: 15, zh: "地中有山，謙；君子以裒多益寡，稱物平施。",
 hv: "Địa trung hữu sơn, Khiêm; quân tử dĩ bầu đa ích quả, xứng vật bình thi.",
 dich: "Trong lòng đất có núi là quẻ Khiêm; người quân tử noi theo mà bớt chỗ nhiều, bù chỗ ít, cân nhắc mà chia cho đều.",
 nguyenTac: "Bớt chỗ thừa, bù chỗ thiếu.",
 giaiThich: "Khôn (đất) trên, Cấn (núi) dưới: núi cao mà chịu nằm dưới đất, có nhiều mà không lộ. Khiêm không chỉ là nhún mình; cái gốc là thấy chỗ mình thừa thì san sang chỗ thiếu. Chia đều ở đây là cân theo nhu cầu, không phải chia bằng nhau.",
 tinhHuong: "Ông Tám ở Bến Tre có bốn người con và hai mẫu vườn dừa. Con cả làm bác sĩ ở thành phố, con út bị tai nạn lao động, đi lại khó, vợ bán rau nuôi hai đứa nhỏ. Ông họp cả nhà, nói rõ: vườn chia bốn nhưng phần út gấp đôi, căn nhà thờ út ở để trông nom; ba người kia nhận ít hơn và nhận cả lời ông giải thích vì sao. Không ai cãi, vì ai cũng đã thấy cảnh em mình.",
 viecHomNay: "Nhìn quanh xem mình đang dư thứ gì (thời gian, đồ dùng, tiền lẻ) mà người bên cạnh đang thiếu, rồi chuyển sang.",
 nhom: "Gia đình"},
{n: 16, zh: "雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。",
 hv: "Lôi xuất địa phấn, Dự; tiên vương dĩ tác nhạc sùng đức, ân tiến chi thượng đế, dĩ phối tổ khảo.",
 dich: "Sấm ra khỏi đất mà vang dậy là quẻ Dự; các vua đời trước noi theo mà làm nhạc để tôn đức, long trọng dâng lên Thượng đế, phối thờ cùng tổ tiên.",
 nguyenTac: "Vui thì có lễ, và nhớ gốc.",
 giaiThich: "Chấn (sấm) trên Khôn (đất): sấm đầu xuân bật khỏi đất, vạn vật rộn lên, đó là niềm vui tự nhiên. Vua xưa biến niềm vui ấy thành nhạc và lễ tế, hướng cái vui về trời và tổ tiên để nó không tan thành buông thả. Vui mà có nghi thức, có đối tượng để biết ơn, thì niềm vui thành sức gắn kết.",
 tinhHuong: "Nhà anh Quang ở Nam Định làm giỗ ông nội. Những năm trước giỗ là một bữa nhậu 15 mâm, họ hàng đến ăn rồi về, trẻ con cắm mặt vào điện thoại. Năm nay anh bàn với các chú làm 6 mâm, nhưng trước khi ăn mỗi nhà cử một người kể một chuyện về ông, chiếu lại ảnh cũ, cho các cháu thắp hương từng đứa một. Bữa giỗ ít rượu hơn mà con anh về nhà còn hỏi tiếp về cụ.",
 viecHomNay: "Kể cho con hoặc cháu một chuyện về ông bà mà chúng chưa từng nghe.",
 nhom: "Gia đình"},
{n: 17, zh: "澤中有雷，隨；君子以嚮晦入宴息。",
 hv: "Trạch trung hữu lôi, Tùy; quân tử dĩ hướng hối nhập yến tức.",
 dich: "Trong đầm có sấm là quẻ Tùy; người quân tử noi theo mà khi trời tối thì vào nhà nghỉ ngơi.",
 nguyenTac: "Tối thì nghỉ, theo nhịp trời.",
 giaiThich: "Đoài (đầm) trên Chấn (sấm) dưới: cuối thu sấm lặn vào đầm, ẩn mình chờ xuân. Tùy là thuận theo; cái phải theo trước nhất là nhịp ngày đêm. Sấm còn biết nghỉ theo mùa, người làm việc không biết nghỉ theo ngày thì sức đâu mà theo việc lớn.",
 tinhHuong: "Anh Sơn lập trình viên ở Cầu Giấy quen làm đến hai, ba giờ sáng vì “đêm yên tĩnh”, sáng chín giờ mới dậy, đến chiều mới tỉnh, một tháng ốm hai lần. Anh thử đặt một luật duy nhất: 23 giờ tắt máy dù đang dở, việc dở ghi vào giấy để sáng làm tiếp. Hai tuần đầu khó chịu; đến tháng thứ hai anh nhận ra lượng việc xong không giảm, lỗi giảm, và lần đầu sau ba năm anh ăn sáng cùng vợ.",
 viecHomNay: "Định giờ tắt mọi màn hình tối nay và làm đúng giờ đó.",
 nhom: "Tu thân"},
{n: 18, zh: "山下有風，蠱；君子以振民育德。",
 hv: "Sơn hạ hữu phong, Cổ; quân tử dĩ chấn dân dục đức.",
 dich: "Dưới núi có gió là quẻ Cổ; người quân tử noi theo mà vực dậy người, nuôi dưỡng đức.",
 nguyenTac: "Nhận việc đã hỏng thì sửa, không trách người trước.",
 giaiThich: "Cấn (núi) trên, Tốn (gió) dưới: gió bị núi chặn, quẩn lại dưới chân núi, lâu ngày sinh mục nát; Cổ là sâu mọt, là việc đã hư từ đời trước để lại. Sửa cái hư phải bắt đầu từ vực người dậy và gây lại nền nếp, không phải từ đập phá hay kể tội.",
 tinhHuong: "Chị Mai nhận lại tiệm bánh mì của mẹ ở Quy Nhơn khi bà ngã bệnh: sổ nợ ghi lẫn vào vở học sinh, lò nướng hỏng một ngăn, hai nhân viên quen làm theo thói quen, khách giảm dần. Chị không nói một câu về cách mẹ làm, chỉ lặng lẽ sửa từng việc: tuần đầu chép lại sổ nợ và đi thu, tuần sau sửa lò, tuần nữa ngồi với hai nhân viên thống nhất lại công thức. Mẹ chị đến thăm tiệm thấy mọi thứ khác mà không thấy mình bị chê.",
 viecHomNay: "Chọn một việc hỏng mà mình đang “để đó” và làm bước sửa đầu tiên.",
 nhom: "Làm việc"},
{n: 19, zh: "澤上有地，臨；君子以教思无窮，容保民无疆。",
 hv: "Trạch thượng hữu địa, Lâm; quân tử dĩ giáo tư vô cùng, dung bảo dân vô cương.",
 dich: "Trên đầm có đất là quẻ Lâm; người quân tử noi theo mà lo dạy dỗ không cùng, bao dung che chở không bờ bến.",
 nguyenTac: "Đến gần người dưới, dạy và che không mỏi.",
 giaiThich: "Khôn (đất) trên, Đoài (đầm) dưới: bờ đất sát mặt đầm, cao mà gần, nhìn xuống thấy rõ. Lâm là người trên đến với người dưới. Đến gần thì mới dạy được, và đã dạy thì phải kiên nhẫn như đất ôm lấy nước, không có chỗ nào bỏ sót.",
 tinhHuong: "Thầy Hòa chủ nhiệm lớp 10 ở một trường huyện Quảng Ngãi có em Tuấn bỏ học ba buổi một tuần. Thay vì gửi giấy mời phụ huynh, thầy đi xe máy 12 cây số đến nhà, biết mẹ Tuấn đi làm xa, em ở với bà và phải đi phụ hồ. Thầy xếp hai bạn gần nhà chở Tuấn đi học, xin trường miễn tiền quỹ, mỗi tuần hỏi em một câu về bà. Tuấn học hết lớp 12, giờ làm thợ điện, mỗi Tết vẫn ghé nhà thầy.",
 viecHomNay: "Hỏi một người mình phụ trách xem việc gì đang làm họ khó, và nghe hết.",
 nhom: "Lãnh đạo"},
{n: 20, zh: "風行地上，觀；先王以省方，觀民設教。",
 hv: "Phong hành địa thượng, Quan; tiên vương dĩ tỉnh phương, quan dân thiết giáo.",
 dich: "Gió đi trên mặt đất là quẻ Quan; các vua đời trước noi theo mà đi xem xét các nơi, xem dân rồi mới đặt ra giáo hóa.",
 nguyenTac: "Đi xem tận nơi rồi mới đặt luật.",
 giaiThich: "Tốn (gió) trên Khôn (đất): gió lướt khắp mặt đất, không bỏ sót ngõ ngách nào. Vua xưa đi tuần các phương để xem dân sống thế nào rồi mới đặt phép dạy. Luật đặt từ bàn giấy thì vướng ở chỗ người đặt không thấy; muốn đặt đúng phải đi xem trước.",
 tinhHuong: "Anh Nam giám đốc nhà máy bao bì ở Hưng Yên định ban hành quy định chấm công vân tay và phạt đi trễ sau khi nghe phòng nhân sự báo ca đêm hay thiếu người. Trước khi ký, anh xuống xưởng đi ca đêm bốn hôm. Anh thấy công nhân không trễ vì lười mà vì xe đưa đón chỉ có một chuyến và nhà ăn ca đêm đóng cửa. Quy định cuối cùng là thêm một chuyến xe và mở bếp đêm; tỷ lệ vắng ca giảm một nửa, không cần phạt ai.",
 viecHomNay: "Trước khi quyết một việc cho người khác, đến chỗ họ làm và đứng nhìn 15 phút.",
 nhom: "Lãnh đạo"},
{n: 21, zh: "雷電噬嗑；先王以明罰敕法。",
 hv: "Lôi điện, Phệ Hạp; tiên vương dĩ minh phạt sắc pháp.",
 dich: "Sấm và chớp là quẻ Phệ Hạp; các vua đời trước noi theo mà làm rõ hình phạt, chỉnh đốn pháp luật.",
 nguyenTac: "Phạt thì rõ, luật thì công khai.",
 giaiThich: "Ly (chớp) trên, Chấn (sấm) dưới: chớp soi sáng, sấm ra uy, hai thứ cùng đến. Phệ Hạp là cắn cho hàm khép lại, tức là trừ cái vật cản ở giữa. Trừ cái cản bằng hình phạt thì hình phạt phải sáng như chớp: ai cũng biết trước điều gì bị phạt và phạt bao nhiêu.",
 tinhHuong: "Hợp tác xã lúa ở Tháp Mười, Đồng Tháp ký được hợp đồng gạo sạch với một siêu thị, nhưng có hai hộ trộn lúa thường vào lô giao, suýt mất hợp đồng. Ban quản trị không xử kín. Họ họp toàn thể, công bố quy chế: lô nào trộn thì hộ đó bị trừ toàn bộ tiền chênh lệch và treo quyền bán qua hợp tác xã một vụ, áp dụng ngay với hai hộ kia trước mặt mọi người. Vụ sau không còn lô nào bị trả.",
 viecHomNay: "Một luật mình đang áp dụng ngầm với con hay nhân viên, nói ra thành lời cho họ biết trước.",
 nhom: "Lãnh đạo"},
{n: 22, zh: "山下有火，賁；君子以明庶政，无敢折獄。",
 hv: "Sơn hạ hữu hỏa, Bí; quân tử dĩ minh thứ chính, vô cảm chiết ngục.",
 dich: "Dưới núi có lửa là quẻ Bí; người quân tử noi theo mà làm sáng các việc thường ngày, không dám dựa vào đó mà xử án.",
 nguyenTac: "Trang sức việc nhỏ, không quyết việc lớn bằng vẻ ngoài.",
 giaiThich: "Cấn (núi) trên, Ly (lửa) dưới: lửa dưới chân núi soi cỏ cây rực rỡ nhưng không soi xa được. Bí là trang sức, là vẻ đẹp bên ngoài; nó đủ để làm sáng việc thường, còn việc hệ trọng như xử án thì không được để cái đẹp bề mặt dẫn dắt.",
 tinhHuong: "Anh Trung trưởng phòng kinh doanh một công ty thiết bị y tế ở quận 1 rất giỏi làm hồ sơ chào hàng: slide đẹp, video mượt, khách xem là có cảm tình. Anh biết rõ sức mạnh ấy nên khi đến lượt mình ký hợp đồng mua hàng hai tỷ từ một nhà cung cấp cũng trình bày rất bắt mắt, anh gác bộ slide của họ sang một bên, đọc từng điều khoản bảo hành và gọi hai khách cũ của họ. Hóa ra thời gian giao hàng thật dài gấp đôi con số trên slide.",
 viecHomNay: "Việc lớn đang cân nhắc, viết ra ba con số thật thay vì cảm giác về nó.",
 nhom: "Làm việc"},
{n: 23, zh: "山附地上，剝；上以厚下，安宅。",
 hv: "Sơn phụ địa thượng, Bác; thượng dĩ hậu hạ, an trạch.",
 dich: "Núi bám sát trên mặt đất là quẻ Bác; người trên noi theo mà bồi dày cho người dưới, để chỗ ở được yên.",
 nguyenTac: "Lúc lở, bồi cho nền dưới trước.",
 giaiThich: "Cấn (núi) trên Khôn (đất) dưới, năm hào âm đẩy một hào dương lên tận cùng: núi đang bị bào mòn, sắp đổ. Núi đứng được là nhờ đất dưới chân; muốn khỏi lở phải bồi cho nền. Lúc suy, người trên không lo giữ phần mình mà lo giữ người dưới, thì nhà mới yên.",
 tinhHuong: "Công ty cơ khí của anh Thắng ở Đà Nẵng mất hai khách lớn trong một quý, phải cắt chi phí 30%. Kế toán đề xuất giảm lương công nhân và cắt bảo hiểm thợ thời vụ. Anh Thắng cắt trước xe công của giám đốc, trả lại văn phòng mặt tiền về xưởng, giảm lương ban điều hành 40%, giữ nguyên lương thợ. Khi có đơn hàng trở lại, thợ lành nghề còn đủ, đối thủ bên cạnh thì đang tuyển lại từ đầu.",
 viecHomNay: "Nếu đang phải cắt giảm, liệt kê các khoản của chính mình trước khi đụng đến khoản của người dưới.",
 nhom: "Tiền của"},
{n: 24, zh: "雷在地中，復；先王以至日閉關，商旅不行，后不省方。",
 hv: "Lôi tại địa trung, Phục; tiên vương dĩ chí nhật bế quan, thương lữ bất hành, hậu bất tỉnh phương.",
 dich: "Sấm ở trong lòng đất là quẻ Phục; các vua đời trước noi theo mà ngày Đông chí đóng cửa ải, khách buôn không đi, vua không đi tuần.",
 nguyenTac: "Mầm vừa nhú, đóng cửa mà dưỡng.",
 giaiThich: "Khôn (đất) trên, Chấn (sấm) dưới: một hào dương vừa sinh ở đáy, như sấm còn nằm trong đất ngày Đông chí. Mầm ấy quý mà yếu, động mạnh là chết. Vua xưa ngày ấy đóng cửa ải, dừng mọi việc để khí dương non được yên; người nay lúc vừa hồi phục cũng phải biết đóng cửa.",
 tinhHuong: "Chị Hương 42 tuổi mổ tuyến giáp ở Bệnh viện Chợ Rẫy, bác sĩ dặn nghỉ bốn tuần. Tuần thứ hai thấy đỡ, chị đã mở máy trả lời khách, định tuần ba đi làm vì “cửa hàng không có mình không được”. Chồng chị thu hết điện thoại công việc, nhờ em gái trông cửa hàng, chị nghỉ đủ bốn tuần và tập đi bộ sáng. Người bạn cùng phòng bệnh về sớm hơn một tuần thì phải nhập viện lại vì nhiễm trùng vết mổ.",
 viecHomNay: "Việc gì mình vừa mới bắt đầu lại được (sức khỏe, thói quen, một mối quan hệ), hôm nay đừng thử sức nó.",
 nhom: "Thời thế"},
{n: 25, zh: "天下雷行，物與无妄；先王以茂對時，育萬物。",
 hv: "Thiên hạ lôi hành, vật dữ vô vọng; tiên vương dĩ mậu đối thời, dục vạn vật.",
 dich: "Dưới trời sấm đi, muôn vật đều được cho sự không càn bậy; các vua đời trước noi theo mà gắng sức thuận thời, nuôi dưỡng muôn vật.",
 nguyenTac: "Thuận mùa mà nuôi, không ép cho sớm.",
 giaiThich: "Càn (trời) trên Chấn (sấm) dưới: sấm xuân đi khắp dưới trời, vạn vật nảy nở đúng mùa, không vật nào làm bậy. Vô vọng là không càn, không mong cầu trái lẽ. Nuôi cây, nuôi người, nuôi việc đều có thời của nó; gắng sức là đúng, nhưng là gắng theo thời, không phải gắng ép thời.",
 tinhHuong: "Anh Đức trồng ba hecta cam ở Cao Phong, Hòa Bình. Người bán vật tư khuyên bón thúc và phun kích để cam chín sớm một tháng, bán được giá đầu vụ. Anh từ chối, chỉ bón theo lịch kỹ thuật viên khuyến nông, tỉa cành, giữ cỏ. Vườn bên cạnh làm theo cách kia được giá một vụ rồi cây suy, hai năm sau phải chặt; vườn anh năm thứ sáu vẫn đều trái, thương lái đến tận vườn đặt trước.",
 viecHomNay: "Một việc đang muốn ép cho nhanh, xem lại nó cần tối thiểu bao lâu và chấp nhận con số đó.",
 nhom: "Làm việc"},
{n: 26, zh: "天在山中，大畜；君子以多識前言往行，以畜其德。",
 hv: "Thiên tại sơn trung, Đại Súc; quân tử dĩ đa thức tiền ngôn vãng hạnh, dĩ súc kỳ đức.",
 dich: "Trời ở trong núi là quẻ Đại Súc; người quân tử noi theo mà ghi nhớ nhiều lời nói việc làm của người xưa, để chứa lấy đức của mình.",
 nguyenTac: "Học việc người trước để chứa vốn cho mình.",
 giaiThich: "Cấn (núi) trên Càn (trời) dưới: núi chứa cả trời trong lòng, chứa được rất lớn. Muốn chứa lớn thì phải có nhiều thứ để chứa; lời nói và việc làm của người đi trước là kho sẵn có, ai chịu nhớ thì được. Đức không tự lớn, nó lớn bằng những gì ta nạp vào.",
 tinhHuong: "Chị Yến 33 tuổi lên giám đốc một công ty logistics 120 người ở Hải Phòng, sớm hơn chị nghĩ mười năm. Chị không đi học thêm bằng cấp mà đặt luật: mỗi tuần đọc một hồi ký hoặc một vụ việc kinh doanh thật, ghi vào một cuốn sổ hai cột, bên trái họ đã làm gì, bên phải nếu là mình ở công ty này thì làm gì. Hai năm sau cuốn sổ dày 300 trang, và khi gặp khủng hoảng thiếu container, chị đã thấy trước một kịch bản tương tự trong sổ.",
 viecHomNay: "Đọc 10 trang về một người đã làm nghề của mình trước mình, ghi lại một câu.",
 nhom: "Tu thân"},
{n: 27, zh: "山下有雷，頤；君子以慎言語，節飲食。",
 hv: "Sơn hạ hữu lôi, Di; quân tử dĩ thận ngôn ngữ, tiết ẩm thực.",
 dich: "Dưới núi có sấm là quẻ Di; người quân tử noi theo mà cẩn thận lời nói, chừng mực ăn uống.",
 nguyenTac: "Giữ miệng: nói có chừng, ăn có mực.",
 giaiThich: "Cấn (núi) trên, Chấn (sấm) dưới: hàm trên đứng yên, hàm dưới động, hình cái miệng đang nhai. Di là nuôi dưỡng. Miệng có hai việc là nói và ăn; cả hai đi ra đi vào qua một cửa, giữ được cửa ấy là giữ được cả thân lẫn danh.",
 tinhHuong: "Anh Bình 45 tuổi, trưởng phòng dự án ở Vũng Tàu, men gan cao, bác sĩ cảnh báo lần thứ hai. Tiếp khách là nghề của anh, mà cứ rượu vào là anh hứa những điều công ty không làm được, hôm sau phải gọi điện rút lại. Anh đặt hai luật và nói trước với cả phòng: tiệc nào cũng chỉ ba ly và về trước 21 giờ; việc gì khách đề nghị trên bàn nhậu thì sáng hôm sau mới trả lời bằng văn bản. Sáu tháng sau men gan về gần bình thường, và lạ là khách tin anh hơn.",
 viecHomNay: "Hôm nay bớt một bữa ăn vặt và nhịn một câu định nói khi đang nóng.",
 nhom: "Tu thân"},
{n: 28, zh: "澤滅木，大過。君子以獨立不懼，遯世无悶。",
 hv: "Trạch diệt mộc, Đại Quá; quân tử dĩ độc lập bất cụ, độn thế vô muộn.",
 dich: "Nước đầm ngập cả cây là quẻ Đại Quá; người quân tử noi theo mà đứng một mình không sợ, lánh đời không buồn.",
 nguyenTac: "Đứng một mình không sợ.",
 giaiThich: "Đoài (đầm) trên, Tốn (cây) dưới: nước dâng ngập cây, việc đã quá mức bình thường, bốn hào dương ở giữa gánh nặng mà hai đầu yếu. Lúc quá, số đông thường im hoặc theo dòng. Người theo tượng ấy thì dám đứng riêng khi cần, và nếu bị gạt ra ngoài thì cũng không lấy đó làm buồn.",
 tinhHuong: "Kỹ sư Hải giám sát một công trình chung cư ở Bình Chánh. Trong cuộc họp, nhà thầu đề nghị tháo giàn giáo sớm hơn ba ngày để kịp tiến độ, chủ đầu tư gật, cả phòng kỹ thuật im lặng. Hải nói không, dẫn số ngày bê tông cần đạt cường độ, rồi về viết văn bản phản đối có ký tên gửi cả ba bên. Anh bị gạt khỏi dự án sau đó; hai tháng sau một công trình gần đó sập sàn vì tháo giáo sớm, và công ty anh gọi anh về làm trưởng bộ phận an toàn.",
 viecHomNay: "Việc mình thấy sai mà cả nhóm đang im, nói ý kiến ấy ra một lần, bằng văn bản.",
 nhom: "Thời thế"},
{n: 29, zh: "水洊至，習坎；君子以常德行，習教事。",
 hv: "Thủy tiến chí, Tập Khảm; quân tử dĩ thường đức hạnh, tập giáo sự.",
 dich: "Nước dồn đến hết lớp này tới lớp khác là quẻ Tập Khảm; người quân tử noi theo mà giữ nết đều đặn, luyện việc dạy dỗ cho quen.",
 nguyenTac: "Hiểm liên tiếp thì giữ nếp quen.",
 giaiThich: "Khảm chồng Khảm: nước hiểm nối nước hiểm, sóng này chưa qua sóng khác đã tới. Nước qua được hiểm vì nó không đổi tính: luôn chảy xuống, luôn lấp đầy. Người gặp khó dồn dập thì không chế thêm cách mới mỗi lần, mà dựa vào nết đều và những việc đã luyện đến mức thành phản xạ.",
 tinhHuong: "Anh Tài lái xe tải tuyến Sài Gòn – Buôn Ma Thuột mười hai năm, mùa mưa đèo nào cũng có xe lật. Anh không tin vào kinh nghiệm cảm tính mà có một tờ giấy ép nhựa dán ở táp lô: 11 mục kiểm trước mỗi chuyến, từ áp suất lốp đến dầu phanh, chạy đến đâu đánh dấu đến đó, mưa to thì dừng ở đúng ba điểm đã định sẵn. Mười hai năm anh chưa gây tai nạn nào; đồng nghiệp bảo anh may, anh bảo anh lặp.",
 viecHomNay: "Việc nguy hiểm hay dễ sai mình làm thường xuyên, viết thành một danh sách kiểm và dán ở chỗ làm.",
 nhom: "Thời thế"},
{n: 30, zh: "明兩作離，大人以繼明照于四方。",
 hv: "Minh lưỡng tác, Ly; đại nhân dĩ kế minh chiếu vu tứ phương.",
 dich: "Ánh sáng nối nhau mà dấy lên là quẻ Ly; bậc đại nhân noi theo mà nối tiếp ánh sáng, soi khắp bốn phương.",
 nguyenTac: "Nối ánh sáng: truyền lại điều mình biết.",
 giaiThich: "Ly chồng Ly: lửa trên lửa, mặt trời hôm nay lặn thì mặt trời mai mọc, ánh sáng không đứt. Không ngọn lửa nào cháy mãi; cái sáng lâu bền là cái sáng được nối tiếp. Người có hiểu biết thì việc lớn nhất không phải tỏa sáng mà là châm được ngọn lửa tiếp theo.",
 tinhHuong: "Bác sĩ Thành, trưởng khoa ngoại một bệnh viện tỉnh ở Thái Bình, còn hai năm nữa nghỉ hưu. Ông đổi lịch: mỗi chiều thứ Sáu không khám, dành cho hai bác sĩ trẻ cùng mổ lại trên mô hình những ca khó ông đã gặp, nói hết cả những lần ông sai. Hôm ông về hưu, khoa không thiếu người mổ ca nặng, và hai bác sĩ kia bắt đầu dành chiều thứ Sáu cho lớp sau nữa.",
 viecHomNay: "Dạy cho một người trẻ hơn một việc mình làm thành thạo, 30 phút.",
 nhom: "Lãnh đạo"},
{n: 31, zh: "山上有澤，咸；君子以虛受人。",
 hv: "Sơn thượng hữu trạch, Hàm; quân tử dĩ hư thụ nhân.",
 dich: "Trên núi có đầm là quẻ Hàm; người quân tử noi theo mà để lòng trống rỗng để đón nhận người.",
 nguyenTac: "Rỗng lòng thì mới nghe được người.",
 giaiThich: "Đoài (đầm) trên, Cấn (núi) dưới: núi phải lõm đỉnh thì mới giữ được nước thành đầm. Hàm là cảm, là hai bên chạm vào nhau. Muốn cảm được người thì lòng phải có chỗ trống; lòng đầy định kiến thì lời người ta nói vào trượt đi hết.",
 tinhHuong: "Chị Phượng ở Thủ Dầu Một hay cãi lại ngay mỗi khi chồng góp ý về cách chị la con, vì “anh có ở nhà đâu mà biết”. Một tối chị thử làm khác: nghe anh nói hết, không ngắt, không giải thích, chỉ hỏi lại hai câu cho rõ, rồi bảo để chị nghĩ. Hôm sau chị nhận ra trong năm điều anh nói có ba điều đúng, và lần đầu anh kể thêm điều anh đã giấu lâu nay: con bé nói với bố là sợ mẹ.",
 viecHomNay: "Trong một cuộc nói chuyện hôm nay, để người kia nói xong hẳn rồi đếm đến ba trước khi trả lời.",
 nhom: "Ứng xử"},
{n: 32, zh: "雷風，恆；君子以立不易方。",
 hv: "Lôi phong, Hằng; quân tử dĩ lập bất dịch phương.",
 dich: "Sấm và gió là quẻ Hằng; người quân tử noi theo mà đứng vững, không đổi hướng.",
 nguyenTac: "Đứng vững, không đổi hướng.",
 giaiThich: "Chấn (sấm) trên, Tốn (gió) dưới: sấm gió luôn đi cùng nhau, luôn động mà cái cách chúng đi cùng nhau thì không đổi. Hằng là bền lâu; bền không phải là đứng im, mà là đổi cách nhưng không đổi hướng. Người giữ được phương thì việc nhỏ lặp lại đủ lâu sẽ thành việc lớn.",
 tinhHuong: "Anh Lâm 50 tuổi, công chức ở Huế, chạy bộ mỗi sáng 30 phút đã mười một năm. Mưa thì chạy hành lang cơ quan, đi công tác thì chạy quanh khách sạn, Tết thì chạy sớm hơn để kịp đi chúc. Anh không thi giải nào, không đếm cây số; chỉ là không bỏ. Bạn cùng tuổi lần lượt mang bệnh mỡ máu, huyết áp, anh thì vẫn cõng được cháu lên dốc chùa Thiên Mụ.",
 viecHomNay: "Thói quen mình đã bỏ dở, làm lại nó hôm nay với lượng nhỏ nhất, chỉ để khỏi đứt.",
 nhom: "Tu thân"},
{n: 33, zh: "天下有山，遯；君子以遠小人，不惡而嚴。",
 hv: "Thiên hạ hữu sơn, Độn; quân tử dĩ viễn tiểu nhân, bất ác nhi nghiêm.",
 dich: "Dưới trời có núi là quẻ Độn; người quân tử noi theo mà xa kẻ xấu, không ghét bỏ mà vẫn nghiêm.",
 nguyenTac: "Xa kẻ xấu: không ghét, chỉ nghiêm.",
 giaiThich: "Càn (trời) trên, Cấn (núi) dưới: núi cao đến đâu trời cũng lùi lên cao hơn, không chạm mà cũng không xung đột. Độn là lui. Lui khỏi kẻ xấu không bằng ghét, vì ghét là còn dây dưa; lui bằng cách giữ khoảng cách và giữ nguyên tắc, để họ không có chỗ bám vào.",
 tinhHuong: "Chị Diệu, kế toán công ty du lịch ở Nha Trang, có một đồng nghiệp hay thêu dệt chuyện về người khác với sếp và từng kể sai về chị. Chị không đối chất, không nói xấu lại, cũng không đi ăn trưa cùng nữa. Mọi trao đổi công việc với người đó chị chuyển sang email, có số liệu, có người nhận cùng; nói chuyện thì lịch sự, ngắn, đúng việc. Một năm sau người kia vẫn nói, nhưng không còn ai trong phòng tin, vì mọi thứ về chị Diệu đều có giấy.",
 viecHomNay: "Với người hay kéo mình vào chuyện không hay, hôm nay trả lời ngắn và chuyển việc sang kênh có lưu vết.",
 nhom: "Ứng xử"},
{n: 34, zh: "雷在天上，大壯；君子以非禮弗履。",
 hv: "Lôi tại thiên thượng, Đại Tráng; quân tử dĩ phi lễ phất lý.",
 dich: "Sấm ở trên trời là quẻ Đại Tráng; người quân tử noi theo mà điều gì trái lễ thì không làm.",
 nguyenTac: "Càng mạnh càng phải giữ lễ.",
 giaiThich: "Chấn (sấm) trên Càn (trời): sấm vang trên trời, bốn hào dương đang lên, sức rất mạnh. Lúc mạnh là lúc dễ làm điều mình muốn nhất, nên cũng là lúc dễ quá nhất. Cái giữ cho sức mạnh không thành tai họa chỉ là một chữ lễ: biết việc gì dù làm được cũng không làm.",
 tinhHuong: "Anh Kiên ở Gia Lâm thắng kiện người hàng xóm lấn 40 phân đất sau hai năm. Có bản án, anh em họ hàng xúi anh thuê người phá hàng rào ngay và nói cho cả xóm biết mặt nhà kia. Anh làm theo thi hành án, mời tổ dân phố chứng kiến, xây lại rào đúng mốc, và sáng hôm sau vẫn chào ông hàng xóm như trước. Hai năm sau nhà bên bán đất, người đến mua hỏi han, chính ông hàng xóm cũ bảo: ở cạnh nhà Kiên yên tâm.",
 viecHomNay: "Việc mình đang có lợi thế tuyệt đối, chọn bớt đi một bước mình có quyền làm.",
 nhom: "Ứng xử"},
{n: 35, zh: "明出地上，晉；君子以自昭明德。",
 hv: "Minh xuất địa thượng, Tấn; quân tử dĩ tự chiêu minh đức.",
 dich: "Ánh sáng ló lên trên mặt đất là quẻ Tấn; người quân tử noi theo mà tự làm sáng cái đức sáng của mình.",
 nguyenTac: "Thăng tiến thì tự soi mình cho sáng.",
 giaiThich: "Ly (mặt trời) trên Khôn (đất): mặt trời mọc, càng lên càng sáng, không ai đẩy nó lên. Tấn là tiến lên. Người được tiến lên thường lo làm cho người khác thấy mình; tượng này dạy ngược lại: lo soi chính mình trước, chỗ nào tối thì sửa, vì càng lên cao càng nhiều người nhìn.",
 tinhHuong: "Chị Quỳnh được bổ nhiệm trưởng phòng tín dụng một chi nhánh ngân hàng ở Cần Thơ, vượt qua hai đồng nghiệp lâu năm. Chị không tổ chức tiệc, không đổi xe, mà thêm vào sổ tay một mục mỗi tối: hôm nay có quyết định nào mình sẽ ngại nếu bị in lên báo không. Có hôm chị ghi một bữa trưa khách hàng mời, hôm sau chị chuyển khoản trả lại. Nửa năm sau, hai người từng tranh vị trí ấy là hai người tin chị nhất.",
 viecHomNay: "Tối nay tự hỏi: hôm nay có việc nào mình làm mà không muốn người khác biết không, rồi sửa nó ngày mai.",
 nhom: "Tu thân"},
{n: 36, zh: "明入地中，明夷；君子以蒞眾，用晦而明。",
 hv: "Minh nhập địa trung, Minh Di; quân tử dĩ lỵ chúng, dụng hối nhi minh.",
 dich: "Ánh sáng chìm vào trong đất là quẻ Minh Di; người quân tử noi theo mà đến với đám đông, dùng vẻ tối mà vẫn sáng bên trong.",
 nguyenTac: "Thời tối, giấu sáng mà vẫn sáng.",
 giaiThich: "Khôn (đất) trên, Ly (mặt trời) dưới: mặt trời đã lặn vào lòng đất, cái sáng bị thương. Lúc ấy người sáng phơi mình ra là bị hại. Cách giữ là bên ngoài lu mờ, hòa với đám đông, bên trong vẫn phân biệt rõ phải trái, không tắt.",
 tinhHuong: "Anh Phong chuyên viên một sở ở miền Trung, có sếp mới hay nghi kỵ người giỏi hơn mình và đã đẩy đi hai người từng góp ý thẳng. Anh thôi phát biểu trong họp, không gửi đề xuất nữa, làm đúng việc được giao và làm rất kỹ. Nhưng anh vẫn lặng lẽ kèm hai bạn trẻ trong phòng viết văn bản, vẫn từ chối ký những tờ trình thiếu căn cứ bằng cách xin thêm hồ sơ. Ba năm sau sếp chuyển, anh được giao phụ trách phòng và hai bạn trẻ kia đã thành nòng cốt.",
 viecHomNay: "Trong môi trường đang khó, làm cho xong và đúng một việc nhỏ mà không nói với ai.",
 nhom: "Thời thế"},
{n: 37, zh: "風自火出，家人；君子以言有物，而行有恆。",
 hv: "Phong tự hỏa xuất, Gia Nhân; quân tử dĩ ngôn hữu vật, nhi hành hữu hằng.",
 dich: "Gió từ lửa mà ra là quẻ Gia Nhân; người quân tử noi theo mà nói có thực chất, làm có nền nếp.",
 nguyenTac: "Nói có nội dung, làm có nếp đều.",
 giaiThich: "Tốn (gió) trên, Ly (lửa) dưới: lửa cháy thì sinh gió, cái bên trong tỏa ra bên ngoài; nếp nhà là ngọn lửa, ảnh hưởng ra xã hội là gió. Nhà yên không nhờ răn dạy nhiều mà nhờ người lớn nói câu nào có việc ấy và làm điều gì thì làm đều, trẻ con nhìn vào mà thành nếp.",
 tinhHuong: "Vợ chồng Tùng và Trang ở Long Biên hay hứa với con: cuối tuần đi công viên, thi xong mua xe đạp, rồi bận mà quên; con bé lớp 4 dần không tin lời bố mẹ và cũng bắt đầu hứa suông với em. Hai vợ chồng đặt luật: đã nói với con là ghi vào lịch chung trên tủ lạnh, không chắc thì nói “bố mẹ chưa chắc”; và một việc đều mỗi tối là 20 phút cả nhà đọc sách, không hôm nào bỏ. Ba tháng sau con bé tự nhắc em “mẹ nói là mẹ làm đấy”.",
 viecHomNay: "Hôm nay không hứa điều gì mình không chắc; đã hứa thì ghi lịch ngay.",
 nhom: "Gia đình"},
{n: 38, zh: "上火下澤，睽；君子以同而異。",
 hv: "Thượng hỏa hạ trạch, Khuê; quân tử dĩ đồng nhi dị.",
 dich: "Trên là lửa, dưới là đầm, là quẻ Khuê; người quân tử noi theo mà hòa đồng ở chỗ chung, giữ khác ở chỗ riêng.",
 nguyenTac: "Chung được chỗ chung, khác được chỗ khác.",
 giaiThich: "Ly (lửa) trên bốc lên, Đoài (đầm) dưới thấm xuống: hai thứ ở cạnh nhau mà đi hai hướng, đó là Khuê, là trái ngược. Trái nhau không nhất thiết phải tách nhau. Người khéo thì tìm chỗ hai bên chung được để giữ nhau, và cho phép chỗ khác nhau cứ khác, không ép.",
 tinhHuong: "Hai anh em Hùng và Hiếu ở Đồng Nai cùng thờ cha mẹ trong một căn nhà hương hỏa, Hùng theo Phật, Hiếu theo đạo vợ là Công giáo. Mấy năm giỗ nào cũng căng vì chuyện thắp hương hay đọc kinh. Họ ngồi lại thống nhất: ngày giỗ hai gia đình cùng về, cùng nấu, cùng ăn; phần nghi lễ mỗi nhà làm theo cách mình trong nửa giờ, nhà kia đứng dự lặng lẽ. Các cháu lớn lên biết cả hai cách và biết rằng khác nhau không phải là bỏ nhau.",
 viecHomNay: "Với người mình đang bất đồng, viết ra một điều hai bên vẫn còn chung, rồi nói với họ điều đó.",
 nhom: "Gia đình"},
{n: 39, zh: "山上有水，蹇；君子以反身修德。",
 hv: "Sơn thượng hữu thủy, Kiển; quân tử dĩ phản thân tu đức.",
 dich: "Trên núi có nước là quẻ Kiển; người quân tử noi theo mà quay lại xét mình, sửa đức.",
 nguyenTac: "Gặp cản, quay về sửa mình trước.",
 giaiThich: "Khảm (nước, hiểm) trên, Cấn (núi, dừng) dưới: trước mặt là hiểm, sau lưng là núi, tiến lùi đều khó, đó là Kiển, là què quặt. Lúc bị chặn mọi phía, cái duy nhất còn đổi được là chính mình. Quay về xét mình không phải là chịu thua, mà là tìm lối ở chỗ duy nhất còn mở.",
 tinhHuong: "Anh Vinh, kỹ sư phần mềm ở Đà Nẵng, xin tăng lương lần thứ hai bị từ chối, bạn bè bảo sếp không biết dùng người. Thay vì gửi đơn nghỉ, anh ngồi liệt kê thật những gì mình làm được trong năm, so với bảng mô tả của bậc trên, và thấy mình thiếu hẳn hai thứ: chưa từng dẫn một dự án từ đầu đến cuối và chưa viết tài liệu cho ai dùng lại. Anh xin nhận một dự án nhỏ làm trưởng, viết tài liệu cho cả nhóm; lần xin thứ ba, chính sếp đề xuất trước.",
 viecHomNay: "Việc đang bị tắc, viết ra một điều ở chính mình mà nếu đổi thì việc có thể khác.",
 nhom: "Tu thân"},
{n: 40, zh: "雷雨作，解；君子以赦過宥罪。",
 hv: "Lôi vũ tác, Giải; quân tử dĩ xá quá hựu tội.",
 dich: "Sấm mưa nổi lên là quẻ Giải; người quân tử noi theo mà tha lỗi lầm, nhẹ bớt tội.",
 nguyenTac: "Việc đã qua thì tha, đừng nhắc.",
 giaiThich: "Chấn (sấm) trên, Khảm (mưa) dưới: cơn giông nổ ra rồi tan, khí trời nhẹ hẳn, cây cỏ tươi lại. Giải là cởi, là gỡ. Sau cơn khó, cái cần gỡ trước nhất là lỗi của người: lỗi vô ý thì tha, tội có ý thì giảm, để người ta còn đường quay lại. Giữ mãi thì không ai thoát ra được, kể cả mình.",
 tinhHuong: "Con trai bà Bảy ở Mỹ Tho mượn xe máy của cậu đi đám cưới, để mất ở bãi gửi. Bà la một trận ngay tối đó, bắt nó viết giấy hứa trả cậu bằng tiền lương, rồi thôi. Suốt mấy tháng sau, bữa cơm nào bà cũng không nhắc lại, chồng bà định nói là bà ngăn. Thằng bé trả hết tiền xe trong tám tháng và từ đó đi đâu cũng khóa cổ xe hai lần; nó bảo với chị gái, nếu mẹ cứ nhắc thì nó đã bỏ đi Bình Dương làm công nhân rồi.",
 viecHomNay: "Một lỗi cũ của người nhà hay đồng nghiệp mà mình vẫn hay nhắc, hôm nay quyết định không nhắc nữa và nói cho họ biết.",
 nhom: "Gia đình"},
{n: 41, zh: "山下有澤，損；君子以懲忿窒欲。",
 hv: "Sơn hạ hữu trạch, Tổn; quân tử dĩ trừng phẫn trất dục.",
 dich: "Dưới núi có đầm là quẻ Tổn; người quân tử noi theo mà răn cơn giận, lấp lòng ham.",
 nguyenTac: "Bớt giận, bớt ham.",
 giaiThich: "Cấn (núi) trên, Đoài (đầm) dưới: đầm khoét sâu dưới chân núi, lấy của dưới bồi cho trên, đó là Tổn, là bớt đi. Hai thứ trong người cần bớt nhất là cơn giận bốc lên như núi và lòng ham sâu như đầm. Bớt được hai thứ ấy thì cái mất bên ngoài hóa ra là được bên trong.",
 tinhHuong: "Anh Hoàng 31 tuổi ở Thanh Xuân, lương 18 triệu, mê đồ công nghệ, mỗi tháng trả góp ba món, điện thoại mới chưa hết góp đã muốn đổi. Anh lập một trang ghi chú tên “Muốn mua”, mỗi thứ thích thì ghi vào kèm ngày, luật là sau 30 ngày còn muốn thì mới mua. Sau nửa năm, trong 14 món ghi vào anh mua 2, và lần đầu anh có 40 triệu trong tài khoản tiết kiệm.",
 viecHomNay: "Một thứ đang muốn mua hôm nay, ghi vào danh sách chờ 30 ngày thay vì bấm mua.",
 nhom: "Tiền của"},
{n: 42, zh: "風雷，益；君子以見善則遷，有過則改。",
 hv: "Phong lôi, Ích; quân tử dĩ kiến thiện tắc thiên, hữu quá tắc cải.",
 dich: "Gió và sấm là quẻ Ích; người quân tử noi theo mà thấy điều tốt thì làm theo, có lỗi thì sửa.",
 nguyenTac: "Thấy tốt thì theo, có lỗi thì sửa ngay.",
 giaiThich: "Tốn (gió) trên, Chấn (sấm) dưới: gió mạnh thêm sấm, sấm mạnh thêm gió, hai thứ làm lợi cho nhau. Ích là thêm vào. Cách làm lợi cho mình nhanh nhất không phải đi tìm cái mới, mà là thấy ai làm tốt thì chuyển sang làm như họ, và thấy mình sai thì đổi ngay, không bào chữa.",
 tinhHuong: "Chị Thảo mở tiệm làm móng ở Gò Vấp, tháng đầu khách thưa. Chị sang tiệm bên cạnh đông khách làm thử một lần, thấy họ lau ghế và đổi khăn trước mặt khách, hôm sau chị làm y vậy. Một khách phàn nàn trên mạng vì bị sai hẹn 40 phút, chị không giải thích mà gọi điện xin lỗi, tặng một lần làm miễn phí, rồi đổi cách đặt lịch. Ba tháng sau tiệm chị kín lịch cuối tuần; chị bảo mình không nghĩ ra gì mới, chỉ không bỏ qua cái gì.",
 viecHomNay: "Hôm nay chọn một cách làm tốt mình thấy ở người khác và làm theo luôn.",
 nhom: "Tu thân"},
{n: 43, zh: "澤上于天，夬；君子以施祿及下，居德則忌。",
 hv: "Trạch thượng vu thiên, Quải; quân tử dĩ thi lộc cập hạ, cư đức tắc kỵ.",
 dich: "Nước đầm dâng lên tận trời là quẻ Quải; người quân tử noi theo mà ban lộc xuống người dưới, giữ khư khư là điều kiêng.",
 nguyenTac: "Có lộc thì chia xuống ngay, đừng giữ.",
 giaiThich: "Đoài (đầm) trên Càn (trời): nước dâng đến trời thì chắc chắn sẽ đổ xuống thành mưa, giữ không được. Quải là quyết, là vỡ. Lộc cũng như nước đầy: phải cho chảy xuống dưới, càng giữ càng nguy. Ôm lấy công đức của mình mà không chia là điều tượng này kiêng nhất.",
 tinhHuong: "Công ty của anh Nhân ở Bắc Ninh trúng gói thầu lắp đặt lớn, lãi hơn dự kiến ba tỷ. Thói quen cũ là treo đến cuối năm xem tình hình rồi thưởng. Lần này anh họp ngay tuần sau khi nghiệm thu, chia thưởng theo công việc thực tế cho đội kỹ thuật đã làm ngày đêm, chuyển khoản trong tháng, công khai cách tính. Cuối năm thị trường khó, anh không có tiền thưởng Tết lớn, nhưng không ai trách vì ai cũng đã nhận phần mình đúng lúc.",
 viecHomNay: "Khoản gì đang nợ người dưới (tiền, lời cảm ơn, lời khen), trả hôm nay.",
 nhom: "Tiền của"},
{n: 44, zh: "天下有風，姤；后以施命誥四方。",
 hv: "Thiên hạ hữu phong, Cấu; hậu dĩ thi mệnh cáo tứ phương.",
 dich: "Dưới trời có gió là quẻ Cấu; bậc vua noi theo mà ban mệnh lệnh, báo khắp bốn phương.",
 nguyenTac: "Lệnh ban ra phải tới được mọi người.",
 giaiThich: "Càn (trời) trên, Tốn (gió) dưới: gió thổi dưới trời, chỗ nào cũng chạm tới. Cấu là gặp gỡ, một hào âm vừa sinh ở dưới gặp năm hào dương. Vua noi gió mà ban lệnh: lệnh phải như gió, đi tới mọi ngóc ngách, không phải chỉ phát ra ở triều đình rồi thôi.",
 tinhHuong: "Bác sĩ Loan điều hành một bệnh viện tư 200 giường ở Thủ Đức, đổi quy trình rửa tay sau một ca nhiễm khuẩn. Lần trước đổi quy trình, bà gửi một email và hai tháng sau khoa sản vẫn làm theo cách cũ. Lần này bà đi từng khoa trong hai ngày, nói chuyện trực tiếp với điều dưỡng trưởng, dán hướng dẫn có hình ở mọi bồn rửa, tuần đầu mỗi ngày đi kiểm một khoa. Sau một tháng, tỷ lệ tuân thủ đo được là 94%, lần trước là 60%.",
 viecHomNay: "Một quy định hay quyết định mình vừa ban ra, kiểm tra xem người cuối cùng trong chuỗi đã nhận được chưa.",
 nhom: "Lãnh đạo"},
{n: 45, zh: "澤上于地，萃；君子以除戎器，戒不虞。",
 hv: "Trạch thượng vu địa, Tụy; quân tử dĩ trừ nhung khí, giới bất ngu.",
 dich: "Đầm ở trên đất là quẻ Tụy; người quân tử noi theo mà sửa sang khí giới, phòng việc không ngờ.",
 nguyenTac: "Tụ đông người thì phòng bất trắc.",
 giaiThich: "Đoài (đầm) trên Khôn (đất): nước tụ trên đất thành đầm, người tụ lại thành đám đông. Tụy là họp lại. Chỗ nào đông người thì chỗ ấy dễ sinh việc không ngờ: tranh chấp, tai nạn, kẻ gian. Người lo việc hội họp thì lo chuyện phòng bị trước khi lo chuyện vui.",
 tinhHuong: "Anh Tú tổ chức họp lớp cấp ba sau 20 năm, hơn 200 người ở một nhà hàng ven biển Sầm Sơn. Ban tổ chức bàn mãi về sân khấu và quà lưu niệm. Anh dành riêng một buổi đến nhà hàng xem lối thoát hiểm, hỏi có tủ thuốc không, thuê sẵn một y tá, hỏi phương án nếu mưa, cử hai bạn tỉnh rượu trông xe và đưa người say về. Tối ấy mưa dông thật và một bạn bị tụt đường huyết; không ai trong buổi họp lớp biết là đã có hai việc suýt hỏng.",
 viecHomNay: "Việc tập trung đông người sắp tới của mình, viết ra ba thứ có thể hỏng và một cách xử lý cho mỗi thứ.",
 nhom: "Làm việc"},
{n: 46, zh: "地中生木，升；君子以順德，積小以高大。",
 hv: "Địa trung sinh mộc, Thăng; quân tử dĩ thuận đức, tích tiểu dĩ cao đại.",
 dich: "Trong đất mọc lên cây là quẻ Thăng; người quân tử noi theo mà thuận theo đức, góp từng chút nhỏ thành cao lớn.",
 nguyenTac: "Góp nhỏ đều đặn thành lớn.",
 giaiThich: "Khôn (đất) trên, Tốn (cây) dưới: cây mọc từ trong đất, mỗi ngày cao thêm không thấy được, nhưng mươi năm thành cổ thụ. Thăng là lên. Lên theo cách của cây là lên bằng tích lũy nhỏ và thuận theo tính tự nhiên, không nhảy cóc.",
 tinhHuong: "Chị Nhung làm hành chính ở Bình Thạnh, lương 12 triệu, bạn bè bảo lương đó thì đừng mơ nhà. Chị đặt lệnh chuyển tự động 1,5 triệu vào tiết kiệm ngay ngày nhận lương, tăng lương thì tăng số đó, thưởng Tết gửi nguyên. Sáu năm sau chị có 230 triệu đặt cọc một căn hộ 45 mét vuông ở Dĩ An, trả góp phần còn lại bằng đúng khoản vẫn chuyển mỗi tháng. Chị bảo chị không cố gì cả, chỉ là không dừng.",
 viecHomNay: "Đặt một lệnh chuyển tự động nhỏ (tiền hoặc thời gian) cho mục tiêu dài hạn, bắt đầu từ kỳ tới.",
 nhom: "Tiền của"},
{n: 47, zh: "澤无水，困；君子以致命遂志。",
 hv: "Trạch vô thủy, Khốn; quân tử dĩ trí mệnh toại chí.",
 dich: "Đầm không có nước là quẻ Khốn; người quân tử noi theo mà dốc cả tính mệnh để giữ trọn chí hướng.",
 nguyenTac: "Cùng đường vẫn giữ chí.",
 giaiThich: "Đoài (đầm) trên, Khảm (nước) dưới: nước rút xuống dưới đáy, đầm cạn trơ, đó là Khốn, là cùng. Lúc cùng, cái mất là hoàn cảnh, cái còn lại là chí. Người theo tượng ấy thì không để hoàn cảnh quyết định mình là ai; cùng đến đâu cũng còn một thứ không giao nộp.",
 tinhHuong: "Anh Thịnh mở quán ăn ở Phú Nhuận, dịch bệnh rồi hết vốn, đóng quán, nợ 800 triệu, trong đó 300 triệu là tiền của bạn bè. Có người khuyên anh về quê đổi số điện thoại. Anh gặp từng chủ nợ, đưa ra lịch trả, đi làm bếp thuê 14 tiếng một ngày, vợ bán hàng online, mỗi tháng trả đủ theo lịch dù chỉ vài triệu một người. Bốn năm sau anh trả hết; người bạn cho vay 100 triệu ngày xưa giờ góp vốn cùng anh mở lại quán.",
 viecHomNay: "Việc đang khó nhất, xác định một điều mình nhất định không bỏ dù việc có hỏng, và viết nó ra.",
 nhom: "Thời thế"},
{n: 48, zh: "木上有水，井；君子以勞民勸相。",
 hv: "Mộc thượng hữu thủy, Tỉnh; quân tử dĩ lao dân khuyến tướng.",
 dich: "Trên gỗ có nước là quẻ Tỉnh; người quân tử noi theo mà khuyến khích người làm việc, khuyên nhau giúp đỡ.",
 nguyenTac: "Như giếng làng: nuôi người và để người giúp nhau.",
 giaiThich: "Khảm (nước) trên, Tốn (gỗ) dưới: gàu gỗ đưa nước lên, hình cái giếng. Giếng ở yên một chỗ mà nuôi cả làng, ai đến cũng múc được, múc mãi không cạn. Người đứng đầu như giếng: không làm thay cho dân mà làm cho dân chịu làm và biết đỡ nhau.",
 tinhHuong: "Cô Hiền trạm trưởng y tế xã ở Hà Tĩnh có năm nhân viên và một xã 9.000 dân, mùa dịch sốt xuất huyết ai cũng kiệt sức. Cô không ôm việc mà chia xã thành năm cụm, mỗi người phụ trách một cụm, tự tuyển hai cộng tác viên thôn, cuối tuần họp 30 phút ai vướng gì thì người khác đỡ. Cô chỉ giữ việc lo thuốc và báo cáo. Hai mùa dịch sau xã cô có số ca thấp nhất huyện, và mấy cộng tác viên thôn nay thành tổ y tế thôn tự chạy.",
 viecHomNay: "Ghép hai người trong nhóm mình thành một cặp để họ đỡ nhau một việc, thay vì mình đỡ cả hai.",
 nhom: "Lãnh đạo"},
{n: 49, zh: "澤中有火，革；君子以治歷明時。",
 hv: "Trạch trung hữu hỏa, Cách; quân tử dĩ trị lịch minh thời.",
 dich: "Trong đầm có lửa là quẻ Cách; người quân tử noi theo mà soạn lịch, làm rõ thời tiết.",
 nguyenTac: "Đổi mới thì phải có lịch rõ từng mốc.",
 giaiThich: "Đoài (đầm) trên, Ly (lửa) dưới: nước và lửa ở chung một chỗ, nhất định một bên phải đổi. Cách là thay đổi. Vua xưa noi theo mà soạn lịch: thay đổi lớn nhất của trời đất là bốn mùa, mà người ta sống được là nhờ biết trước mùa nào đến khi nào. Muốn đổi mới mà không loạn thì phải nói được cái gì đổi vào lúc nào.",
 tinhHuong: "Xưởng may của anh Lộc ở Hóc Môn gia công cho người khác mười năm, nay quyết chuyển sang làm thương hiệu bán online. Lần thử đầu, anh vừa nhận gia công vừa may mẫu, thợ không biết ưu tiên gì, ba tháng rối không ra nổi một mẫu. Lần hai anh treo một tờ lịch lớn: tháng 1 đến 3 vẫn gia công đủ 80%, 20% làm mẫu; tháng 4 ra 10 mẫu, chụp hình; tháng 6 còn 50% gia công; tháng 10 dừng gia công. Thợ nhìn lịch là biết tuần này làm gì, và đến tháng 10 xưởng chuyển xong đúng hẹn.",
 viecHomNay: "Việc đang muốn thay đổi, viết ra ba mốc ngày: bắt đầu, nửa chừng, xong.",
 nhom: "Làm việc"},
{n: 50, zh: "木上有火，鼎；君子以正位凝命。",
 hv: "Mộc thượng hữu hỏa, Đỉnh; quân tử dĩ chính vị ngưng mệnh.",
 dich: "Trên gỗ có lửa là quẻ Đỉnh; người quân tử noi theo mà ngồi đúng ngôi vị, giữ vững sứ mệnh.",
 nguyenTac: "Ngồi đúng ghế, làm đúng việc của ghế ấy.",
 giaiThich: "Ly (lửa) trên, Tốn (gỗ) dưới: củi đun dưới vạc, hình cái đỉnh nấu ăn. Đỉnh đứng vững nhờ ba chân đặt ngay ngắn; lệch một chân là đổ cả nồi. Người nhận một vị trí thì việc đầu là đặt mình đúng vào vị trí đó, làm việc của vị trí đó, không với xuống cũng không với lên.",
 tinhHuong: "Anh Quân từ kỹ sư giỏi nhất được lên giám đốc chi nhánh một công ty tự động hóa ở Hải Dương. Tháng đầu anh vẫn ngồi gỡ lỗi tủ điện thay cho kỹ sư cũ vì thấy họ chậm, trong khi hợp đồng không ai ký, kế hoạch quý không ai duyệt. Người sếp cũ gọi hỏi một câu: ghế ấy ai đang ngồi? Anh về giao việc kỹ thuật cho hai trưởng nhóm, mình chỉ xem kết quả, dành ngày cho khách hàng và kế hoạch. Quý sau chi nhánh lần đầu đạt chỉ tiêu, và kỹ sư cũ gỡ lỗi nhanh hơn khi không có anh đứng sau lưng.",
 viecHomNay: "Liệt kê việc hôm nay, gạch những việc không thuộc vị trí của mình và giao đi một việc.",
 nhom: "Lãnh đạo"},
{n: 51, zh: "洊雷，震；君子以恐懼修省。",
 hv: "Tiến lôi, Chấn; quân tử dĩ khủng cụ tu tỉnh.",
 dich: "Sấm nổ dồn dập là quẻ Chấn; người quân tử noi theo mà biết sợ, sửa mình và tự xét.",
 nguyenTac: "Gặp biến thì sợ cho đúng: sửa mình.",
 giaiThich: "Chấn chồng Chấn: sấm nối sấm, chấn động liên hồi. Sấm làm người ta sợ, nhưng sấm không hại ai; cái sợ ấy dùng để tỉnh lại, soát xem mình đã lơi lỏng ở đâu. Biến cố là tiếng sấm; người khôn không hoảng loạn cũng không bỏ ngoài tai, mà nhân đó mà sửa.",
 tinhHuong: "Anh Khánh 48 tuổi ở Biên Hòa đi khám tổng quát theo công ty, nhận kết quả tiểu đường tuýp 2. Hai ngày đầu anh hoảng, lên mạng đọc đủ thứ, định bỏ việc đi chữa thuốc nam. Vợ anh bảo: sợ thì sợ cho đúng chỗ. Anh ngồi viết lại một ngày của mình: ngủ 5 tiếng, hai ly trà sữa, ăn tối 22 giờ, không đi bộ. Anh sửa từng thứ theo hẹn bác sĩ, ba tháng sau đường huyết về ngưỡng kiểm soát; anh bảo cái kết quả xét nghiệm ấy là tiếng sấm cứu mình.",
 viecHomNay: "Việc vừa làm mình giật mình gần đây, viết ra một thói quen của mình đã góp phần tạo ra nó.",
 nhom: "Thời thế"},
{n: 52, zh: "兼山，艮；君子以思不出其位。",
 hv: "Kiêm sơn, Cấn; quân tử dĩ tư bất xuất kỳ vị.",
 dich: "Hai núi kề nhau là quẻ Cấn; người quân tử noi theo mà nghĩ không vượt ra ngoài chỗ đứng của mình.",
 nguyenTac: "Nghĩ trong phận mình, đừng ôm việc người.",
 giaiThich: "Cấn chồng Cấn: núi chồng núi, đứng yên hẳn. Cấn là dừng. Dừng khó nhất không phải ở tay chân mà ở đầu óc: nghĩ lan sang việc không phải của mình, lo thay người khác, rồi mệt và sinh chuyện. Giữ ý nghĩ trong phạm vi mình có thể làm được thì tâm mới yên.",
 tinhHuong: "Chị Trinh ở Tây Hồ mất ngủ triền miên vì lo: em chồng sắp sinh mà chưa có nhà, bạn thân đang ly hôn, con đồng nghiệp thi trượt. Chị gọi điện khuyên bảo khắp nơi, có người khó chịu, việc nhà chị thì bỏ bê, chồng con nói chị lo chuyện thiên hạ. Chị thử một việc: mỗi tối viết ra điều đang lo rồi chia hai cột, cột mình làm được gì và cột không phải việc mình; cột sau chị gạch đi. Sau một tháng, cột trước chỉ còn ba dòng và chị ngủ được.",
 viecHomNay: "Viết ra ba điều đang lo, gạch những điều không nằm trong tay mình, chỉ làm điều còn lại.",
 nhom: "Tu thân"},
{n: 53, zh: "山上有木，漸；君子以居賢德，善俗。",
 hv: "Sơn thượng hữu mộc, Tiệm; quân tử dĩ cư hiền đức, thiện tục.",
 dich: "Trên núi có cây là quẻ Tiệm; người quân tử noi theo mà ở yên trong đức tốt, làm đẹp phong tục dần dần.",
 nguyenTac: "Đổi nếp thì từ từ, bằng chính mình trước.",
 giaiThich: "Tốn (cây) trên, Cấn (núi) dưới: cây trên núi lớn chậm, mỗi năm một vòng, nhưng vì chậm mà rễ bám chắc đá. Tiệm là tiến dần. Muốn đổi nếp của một nhà, một nơi, không thể ra lệnh; phải tự mình sống cái nếp ấy trước, lâu ngày người quanh nhìn mà theo.",
 tinhHuong: "Anh Tiến về ở rể nhà vợ ở Hải Phòng, nếp nhà là đàn ông ăn xong đứng dậy, phụ nữ dọn. Anh thấy chướng nhưng không nói, vì nói là thành chuyện con rể dạy nhà vợ. Bữa đầu anh chỉ bê mâm xuống bếp rồi lên, tuần sau rửa bát luôn; bố vợ nhìn không nói gì. Hai tháng sau cậu em vợ bắt đầu dọn cùng. Đến Tết năm ấy, chính bố vợ đứng lên bê mâm, và mẹ vợ nói với con gái: nhà này đổi từ ngày có thằng Tiến.",
 viecHomNay: "Nếp xấu nào trong nhà hay cơ quan mình muốn đổi, hôm nay tự làm khác đi một lần, không nói gì.",
 nhom: "Gia đình"},
{n: 54, zh: "澤上有雷，歸妹；君子以永終知敝。",
 hv: "Trạch thượng hữu lôi, Quy Muội; quân tử dĩ vĩnh chung tri tệ.",
 dich: "Trên đầm có sấm là quẻ Quy Muội; người quân tử noi theo mà muốn giữ lâu dài thì phải biết trước chỗ sẽ hỏng.",
 nguyenTac: "Muốn bền lâu, biết trước chỗ sẽ hỏng.",
 giaiThich: "Chấn (sấm) trên, Đoài (đầm) dưới: sấm động trên mặt đầm, nước theo sấm mà xao động, như cô gái trẻ theo người về nhà chồng vì cảm xúc. Quy Muội là gả em gái, là việc kết hợp bắt đầu bằng rung động. Rung động không đủ cho cả đời; muốn trọn thì ngay lúc đầu phải nhìn thấy chỗ sau này sẽ rạn mà lo trước.",
 tinhHuong: "Hà và Nghĩa yêu nhau hai năm, định cưới sau Tết. Mọi cuộc hẹn đều bàn tiệc cưới và chụp ảnh. Một chị đồng nghiệp đã ly hôn khuyên Hà một buổi tối ngồi nói với nhau về bốn chuyện: tiền ai giữ và tiêu thế nào, ở riêng hay ở với bố mẹ Nghĩa, bao giờ có con và ai nghỉ trông, Tết về bên nào. Buổi nói chuyện ấy căng, hai người giận nhau ba ngày, rồi thống nhất được ba chuyện và đồng ý chuyện thứ tư sẽ bàn lại mỗi năm. Cưới bốn năm, họ cãi nhau nhiều việc, nhưng chưa lần nào vì bốn việc đó.",
 viecHomNay: "Một mối quan hệ hay hợp tác đang vui, viết ra điều dễ làm nó hỏng nhất sau hai năm, rồi nói với người kia.",
 nhom: "Gia đình"},
{n: 55, zh: "雷電皆至，豐；君子以折獄致刑。",
 hv: "Lôi điện giai chí, Phong; quân tử dĩ chiết ngục trí hình.",
 dich: "Sấm và chớp cùng đến là quẻ Phong; người quân tử noi theo mà xét án cho rõ, thi hành hình phạt đến nơi.",
 nguyenTac: "Lúc thịnh, việc khó phải xử dứt điểm.",
 giaiThich: "Chấn (sấm) trên, Ly (chớp) dưới: chớp soi, sấm quyết, cả hai đến cùng lúc, đó là Phong, là thịnh lớn. Lúc thịnh người ta hay nể nang, để việc khó trôi vì sợ mất vui. Tượng này dạy ngược lại: đang sáng và đang mạnh thì phải xử ngay việc mập mờ, vì để đến lúc suy thì không còn sức mà xử.",
 tinhHuong: "Công ty phần mềm của chị Oanh ở quận 7 đang tăng trưởng mạnh, 150 người, vừa gọi được vốn. Hai phó giám đốc mâu thuẫn ngầm nửa năm: một người giữ lại nhân sự giỏi không cho chuyển bộ phận, người kia chặn ngân sách đối phương. Chị Oanh ngại xử vì đang kỳ tốt, sợ mất một trong hai. Khi năm nhân viên giỏi nghỉ cùng tháng, chị mới họp riêng từng người, lấy đủ dữ liệu, rồi quyết: tách rõ hai mảng, một người chuyển vai, công bố toàn công ty. Chị nói giá như làm từ tháng thứ hai thì không mất năm người.",
 viecHomNay: "Việc mập mờ mình đang né vì mọi thứ đang ổn, đặt lịch xử lý nó trong tuần này.",
 nhom: "Lãnh đạo"},
{n: 56, zh: "山上有火，旅；君子以明慎用刑，而不留獄。",
 hv: "Sơn thượng hữu hỏa, Lữ; quân tử dĩ minh thận dụng hình, nhi bất lưu ngục.",
 dich: "Trên núi có lửa là quẻ Lữ; người quân tử noi theo mà sáng suốt, thận trọng khi dùng hình phạt, không để án kéo dài.",
 nguyenTac: "Đất khách: thận trọng, và không dây dưa.",
 giaiThich: "Ly (lửa) trên, Cấn (núi) dưới: lửa cháy trên núi, lan nhanh và không ở lâu một chỗ, như người đi đường xa qua nơi lạ. Lữ là lữ khách. Ở đất khách, việc gì cũng phải xem xét kỹ vì mình không hiểu hết chỗ ấy, nhưng xem xong thì xử gọn, không để việc lằng nhằng níu chân mình lại.",
 tinhHuong: "Anh Cảnh sang Nhật làm hàn công theo chương trình kỹ năng, nhóm có một quản lý người Việt hay trừ tiền tăng ca vô cớ. Mấy anh em bàn nhau bỏ việc ra ngoài, hoặc nhịn ba năm. Anh Cảnh chụp lại bảng chấm công hai tháng, hỏi một người Nhật ở nghiệp đoàn cách làm đúng, rồi nộp đơn lên nghiệp đoàn một lần, đủ chứng cứ, lời lẽ nhẹ. Việc được giải quyết trong ba tuần, anh không bỏ việc, không kết thù, và hết hạn về nước với đủ tiền như kế hoạch.",
 viecHomNay: "Việc vướng mắc ở nơi mình là người mới, hôm nay hỏi một người hiểu luật nơi đó cách xử lý đúng rồi làm ngay.",
 nhom: "Ứng xử"},
{n: 57, zh: "隨風，巽；君子以申命行事。",
 hv: "Tùy phong, Tốn; quân tử dĩ thân mệnh hành sự.",
 dich: "Gió nối theo gió là quẻ Tốn; người quân tử noi theo mà nhắc lại mệnh lệnh rồi mới làm việc.",
 nguyenTac: "Nhắc đi nhắc lại rồi mới làm.",
 giaiThich: "Tốn chồng Tốn: gió nối gió, thổi mãi không dứt, nên thấm được vào mọi khe hở. Tốn là thuận, là vào. Lệnh nói một lần không ai nhớ; nói đi nói lại nhẹ nhàng như gió thì người ta nghe lúc nào không biết. Việc làm thì có một lần, nhưng nhắc thì phải nhiều lần.",
 tinhHuong: "Chị Vân phụ trách an toàn một công trường 300 công nhân ở Nhơn Trạch. Trước đây mỗi quý có một buổi tập huấn hai tiếng, ký tên đủ, rồi tai nạn vẫn xảy ra. Chị bỏ tập huấn dài, thay bằng năm phút mỗi sáng trước giờ làm: hôm nay làm gì, ba điều phải nhớ, ngày nào cũng ba điều ấy đổi theo việc. Thợ ban đầu cười vì nhắc như nhắc trẻ con; sau sáu tháng công trường không có tai nạn mất ngày công, và chính thợ nhắc nhau câu của chị.",
 viecHomNay: "Việc quan trọng mình đã dặn người khác một lần, hôm nay nhắc lại lần hai bằng cách khác.",
 nhom: "Làm việc"},
{n: 58, zh: "麗澤，兌；君子以朋友講習。",
 hv: "Lệ trạch, Đoài; quân tử dĩ bằng hữu giảng tập.",
 dich: "Hai đầm liền nhau là quẻ Đoài; người quân tử noi theo mà cùng bạn bè bàn bạc và luyện tập.",
 nguyenTac: "Học với bạn, đừng học một mình.",
 giaiThich: "Đoài chồng Đoài: hai đầm thông nhau, nước bên này cạn thì bên kia chảy sang, cùng đầy. Đoài là vui, là nói. Niềm vui bền nhất là cùng bạn giảng cho nhau điều mình hiểu và tập lại điều mình học; học một mình thì nước đứng, học với bạn thì nước chảy.",
 tinhHuong: "Bốn thợ điện lạnh ở Thanh Hóa quen nhau từ một khóa học ngắn, mỗi người làm một nơi. Họ lập nhóm Zalo với một luật: tuần nào cũng mỗi người kể một lỗi đã gặp và cách mình sửa, kèm ảnh, không được chỉ hỏi mà không kể. Ba năm sau nhóm có 600 ca lỗi được ghi lại, ai gặp máy lạ tra lại là có người từng làm. Hai người trong nhóm giờ mở được cửa hàng, và họ vẫn kể lỗi mỗi tuần.",
 viecHomNay: "Kể cho một người cùng nghề một lỗi mình vừa mắc và cách sửa, rồi hỏi lại họ một lỗi của họ.",
 nhom: "Tu thân"},
{n: 59, zh: "風行水上，渙；先王以享于帝立廟。",
 hv: "Phong hành thủy thượng, Hoán; tiên vương dĩ hưởng vu đế, lập miếu.",
 dich: "Gió đi trên mặt nước là quẻ Hoán; các vua đời trước noi theo mà tế Thượng đế, dựng tông miếu.",
 nguyenTac: "Khi tan rã, dựng một chỗ chung để gom lòng.",
 giaiThich: "Tốn (gió) trên, Khảm (nước) dưới: gió thổi trên mặt nước làm nước tan ra từng mảng, đó là Hoán, là ly tán. Lúc lòng người tản mát, vua xưa không ra lệnh gom mà lập đền thờ, đặt lễ tế: tạo ra một chỗ thiêng, một việc chung mà ai cũng muốn về. Người ta tụ lại quanh cái mình cùng kính, không tụ vì bị gọi.",
 tinhHuong: "Dòng họ Nguyễn Đình ở một xã Nghệ An có bảy chi, con cháu đi khắp nơi, giỗ tổ mỗi năm về được vài chục người già, lớp trẻ không biết mặt nhau, đã có hai đám cưới suýt lấy nhầm người trong họ. Ông trưởng họ không kêu gọi đoàn kết. Ông sửa nhà thờ họ, lập quỹ khuyến học trao mỗi mùng 4 Tết cho cháu đỗ đại học, in gia phả có ảnh, mở nhóm trực tuyến đăng tin vui buồn từng nhà. Năm năm sau giỗ tổ về 400 người, và lớp trẻ tự lập đội bóng đá của họ.",
 viecHomNay: "Nhóm nào của mình đang rời rạc (gia đình, bạn cũ, đội làm việc), tạo một dịp chung nhỏ và gửi lời mời hôm nay.",
 nhom: "Gia đình"},
{n: 60, zh: "澤上有水，節；君子以制數度，議德行。",
 hv: "Trạch thượng hữu thủy, Tiết; quân tử dĩ chế số độ, nghị đức hạnh.",
 dich: "Trên đầm có nước là quẻ Tiết; người quân tử noi theo mà đặt ra mức độ, bàn định đức hạnh.",
 nguyenTac: "Đặt mức, đặt hạn cho mọi thứ.",
 giaiThich: "Khảm (nước) trên Đoài (đầm) dưới: đầm chứa nước có giới hạn, đầy thì tràn, nên phải có bờ. Tiết là đốt tre, là chừng mực. Đặt số và độ cho tiền bạc, thời gian, việc làm, rồi lấy đó mà xét hành vi của mình; không có mức thì không biết mình đang quá hay thiếu.",
 tinhHuong: "Vợ chồng Hoa và Sang ở Bình Tân thu nhập 35 triệu mà tháng nào cũng hết, cãi nhau về tiền mỗi cuối tháng, không ai biết tiền đi đâu. Họ ngồi một tối đặt mức: ăn uống 9 triệu, học con 5 triệu, đi lại 2,5 triệu, hiếu hỉ 2 triệu, mỗi người 1,5 triệu tiêu riêng không hỏi nhau, 6 triệu gửi tiết kiệm ngay đầu tháng, còn lại cho phát sinh. Tháng đầu vỡ hai mục; họ chỉ chỉnh số chứ không bỏ. Đến tháng thứ tư, lần đầu cuối tháng còn tiền và không cãi nhau.",
 viecHomNay: "Chọn một khoản chi hay một việc tốn thời gian và đặt cho nó một con số trần ngay hôm nay.",
 nhom: "Tiền của"},
{n: 61, zh: "澤上有風，中孚；君子以議獄緩死。",
 hv: "Trạch thượng hữu phong, Trung Phu; quân tử dĩ nghị ngục hoãn tử.",
 dich: "Trên đầm có gió là quẻ Trung Phu; người quân tử noi theo mà bàn xét kỹ việc án, hoãn việc xử chết.",
 nguyenTac: "Xét kỹ trước khi phạt nặng.",
 giaiThich: "Tốn (gió) trên, Đoài (đầm) dưới: gió lướt trên đầm, nước cảm được gió mà gợn; Trung Phu là lòng tin thật từ bên trong. Người có lòng thành thì khi xử người khác luôn ngờ rằng mình có thể chưa biết hết, nên bàn kỹ, và việc không đảo ngược được thì hoãn lại. Phạt nhẹ sai còn sửa được, phạt nặng sai thì không.",
 tinhHuong: "Anh Phát chủ một cửa hàng vật liệu xây dựng ở Buôn Ma Thuột phát hiện quỹ hụt 28 triệu, camera cho thấy chỉ cô thu ngân Ly đứng quầy hôm đó. Anh định đuổi việc và báo công an ngay chiều hôm ấy. Vợ anh can, bảo chờ đến mai. Tối đó anh ngồi rà lại phần mềm bán hàng, thấy một đơn trả hàng 28 triệu bị ghi hai lần do lỗi đồng bộ, tiền không hề mất. Sáng hôm sau anh xin lỗi Ly; cô làm với anh đến giờ đã bảy năm và quản lý cả ba cửa hàng.",
 viecHomNay: "Việc mình đang định xử nặng một ai đó, hoãn lại 24 giờ và tìm thêm một nguồn thông tin.",
 nhom: "Lãnh đạo"},
{n: 62, zh: "山上有雷，小過；君子以行過乎恭，喪過乎哀，用過乎儉。",
 hv: "Sơn thượng hữu lôi, Tiểu Quá; quân tử dĩ hành quá hồ cung, tang quá hồ ai, dụng quá hồ kiệm.",
 dich: "Trên núi có sấm là quẻ Tiểu Quá; người quân tử noi theo mà cư xử hơi quá về cung kính, việc tang hơi quá về thương xót, chi dùng hơi quá về tiết kiệm.",
 nguyenTac: "Nếu có quá, hãy quá về phía khiêm, thương, kiệm.",
 giaiThich: "Chấn (sấm) trên, Cấn (núi) dưới: sấm nổ trên đỉnh núi, tiếng to hơn bình thường một chút, đó là Tiểu Quá, là quá một chút ở việc nhỏ. Đời không thể lúc nào cũng vừa khít; nếu phải lệch thì nên lệch về phía cung kính hơn, thương xót hơn, tiết kiệm hơn, vì lệch về phía ấy không hại ai.",
 tinhHuong: "Đồng nghiệp cùng phòng của anh Thiện ở Bắc Giang mất mẹ ở quê cách 60 cây số. Phòng góp phong bì và cử đại diện đi; anh Thiện đi riêng từ sáng sớm, đến trước giờ viếng, ở lại phụ bưng bê đến chiều, phong bì anh bỏ bằng mọi người chứ không hơn. Về sau người đồng nghiệp ấy nói rằng trong mấy trăm người đến, anh nhớ nhất người đứng cạnh mình lúc hạ huyệt. Hơi quá về lòng thương thì không bao giờ là quá.",
 viecHomNay: "Hôm nay chọn một việc nhỏ để làm kỹ hơn mức cần: cúi chào thấp hơn, hỏi thăm lâu hơn, hoặc tiêu ít hơn.",
 nhom: "Ứng xử"},
{n: 63, zh: "水在火上，既濟；君子以思患而豫防之。",
 hv: "Thủy tại hỏa thượng, Ký Tế; quân tử dĩ tư hoạn nhi dự phòng chi.",
 dich: "Nước ở trên lửa là quẻ Ký Tế; người quân tử noi theo mà nghĩ đến tai họa để phòng trước.",
 nguyenTac: "Việc xong rồi là lúc nghĩ đến cái hỏng.",
 giaiThich: "Khảm (nước) trên, Ly (lửa) dưới: nước trên lửa thì nấu chín được, mọi hào đều đúng vị, việc đã thành. Nhưng nước sôi lâu thì cạn, lửa cháy lâu thì tắt; cái đã xong là cái bắt đầu hỏng. Người khôn lúc xong việc không ăn mừng trước mà ngồi nghĩ nó sẽ hỏng ở đâu và chặn trước.",
 tinhHuong: "Anh Dương thầu xây nhà dân ở Long Thành, bàn giao một căn ba tầng đúng hẹn, chủ nhà hài lòng. Thay vì nhận tiền rồi đi, anh đưa chủ nhà một tờ giấy: những chỗ dễ hỏng trong hai năm đầu (thấm chân tường vệ sinh, nứt chân chim, nghẹt ống thoát sân thượng), cách tự kiểm mỗi mùa mưa, và số điện thoại bảo hành. Anh đặt lịch sau mùa mưa đầu tiên tự đến xem. Chủ nhà ấy giới thiệu cho anh bốn căn tiếp theo, và không căn nào gọi anh vì sự cố bất ngờ.",
 viecHomNay: "Việc vừa hoàn thành, viết ra ba chỗ nó có thể hỏng trong một năm và một việc phòng cho mỗi chỗ.",
 nhom: "Làm việc"},
{n: 64, zh: "火在水上，未濟；君子以慎辨物居方。",
 hv: "Hỏa tại thủy thượng, Vị Tế; quân tử dĩ thận biện vật cư phương.",
 dich: "Lửa ở trên nước là quẻ Vị Tế; người quân tử noi theo mà cẩn thận phân biệt từng thứ, đặt mỗi thứ vào đúng chỗ.",
 nguyenTac: "Việc chưa xong: phân loại và đặt đúng chỗ.",
 giaiThich: "Ly (lửa) trên bốc lên, Khảm (nước) dưới chảy xuống: hai thứ không gặp nhau, chưa nấu được gì, mọi hào đều sai vị. Vị Tế là chưa xong, và Kinh Dịch kết thúc bằng chữ chưa xong. Việc chưa thành thì đừng vội thành; trước hết nhìn cho rõ từng thứ là gì và nên ở đâu, đặt lại cho đúng chỗ, rồi việc tự có đường đi.",
 tinhHuong: "Chị Xuân chuyển nhà từ quận 3 về Nhà Bè, ba tuần sau vẫn còn 30 thùng chưa dỡ chất ở phòng khách, cả nhà tìm cái gì cũng không thấy, chồng con cáu. Chị dừng việc dỡ, dành một buổi dán nhãn lại mọi thùng theo phòng và theo mức cần: cần ngay, cần trong tháng, có thể cho. Rồi mỗi tối dỡ hai thùng theo đúng thứ tự, thùng “có thể cho” mang đi tặng luôn. Mười ngày sau phòng khách trống, và chị phát hiện trong ba mươi thùng có tám thùng nhà chị không cần nữa.",
 viecHomNay: "Việc đang dở dang nhất, chia các phần của nó thành ba nhóm: làm ngay, làm sau, bỏ đi.",
 nhom: "Làm việc"}
];
